window.BIBLIE_NARRACOES = {"o-semeador":{"audio":"audio/o-semeador.mp3?v=95bc046de111","quadros":[[0,"À beira do mar, Jesus ensina uma multidão reunida na margem. Ele conta que um semeador saiu para espalhar sementes. As que caíram no caminho ficaram expostas. Vieram as aves e as comeram antes que pudessem brotar.",[[110,0,1],[209,2,5],[634,8,2],[802,11,3],[1479,16,5],[2079,22,6],[2639,29,3],[2824,33,8],[3496,42,7],[4144,50,2],[4308,53,6],[6017,61,3],[6264,65,5],[6747,71,3],[6897,75,2],[7042,78,8],[7794,87,4],[8251,92,4],[8572,97,8],[9204,106,8],[11284,116,2],[11488,119,3],[11656,123,6],[12199,130,2],[12353,133,7],[12929,141,7],[13563,149,8],[15689,159,6],[16190,166,2],[16396,169,4],[16913,174,1],[17021,176,2],[17212,179,7],[17799,187,5],[18263,193,3],[18417,197,8],[19101,206,6]]],[20941,"Em terreno pedregoso, as sementes brotaram depressa, mas faltou profundidade para as raízes. Quando o sol esquentou, as plantas secaram. Outras sementes caíram entre espinhos. Os espinhos cresceram junto com elas, até sufocar o que começava a nascer.",[[20941,0,2],[21131,3,7],[21709,11,9],[22983,22,2],[23163,25,8],[23888,34,8],[24482,43,8],[25581,53,3],[25895,57,6],[26404,64,12],[27555,77,4],[27854,82,2],[28035,85,6],[29928,93,6],[30324,100,1],[30380,102,3],[30778,106,9],[31743,117,2],[31978,120,7],[32521,128,7],[34254,137,6],[34747,144,8],[35540,153,6],[36121,160,5],[36505,166,8],[38438,176,2],[38601,179,8],[39300,188,9],[39995,198,5],[40488,204,3],[40765,208,4],[41598,214,3],[41952,218,7],[42680,226,1],[42769,228,3],[42951,232,8],[43745,241,1],[43813,243,6]]],[45637,"Em boa terra, as sementes cresceram e deram uma colheita abundante. Jesus explica aos discípulos que o terreno representa quem ouve. A palavra pode ser esquecida, abandonada na dificuldade ou sufocada pelas preocupações. A boa terra é quem a acolhe e persevera até dar fruto.",[[45637,0,2],[45809,3,3],[46166,7,5],[47008,14,2],[47189,17,8],[47961,26,9],[48786,36,1],[48891,38,5],[49322,44,3],[49539,48,8],[50213,57,9],[52136,68,5],[52723,74,7],[53435,82,3],[53640,86,10],[54582,97,3],[54725,101,1],[54799,103,7],[55380,111,10],[56277,122,4],[56567,127,4],[58174,133,1],[58266,135,7],[58948,143,4],[59337,148,3],[59606,152,9],[60794,163,10],[61658,174,2],[61825,177,11],[62865,189,2],[63026,192,8],[63812,201,5],[64338,207,12],[66692,221,1],[66812,223,3],[67172,227,5],[67642,233,1],[67785,235,4],[68077,240,1],[68158,242,6],[68752,249,1],[68858,251,9],[69590,261,3],[69924,265,3],[70184,269,5]]]]},"a-semente-que-cresce":{"audio":"audio/a-semente-que-cresce.mp3?v=bc09227d72ee","quadros":[[0,"Jesus compara o Reino de Deus ao trabalho de um homem que lança sementes na terra. Depois de semear, o agricultor volta à sua rotina. Ele dorme, levanta e atravessa dias e noites enquanto algo começa a acontecer sob o solo.",[[112,0,5],[719,6,7],[1332,14,1],[1419,16,5],[1904,22,2],[2049,25,4],[2461,30,2],[2629,33,8],[3283,42,2],[3427,45,2],[3589,48,5],[3967,54,3],[4133,58,5],[4598,64,8],[5418,73,2],[5618,76,5],[7234,83,6],[7785,90,2],[7920,93,6],[8890,101,1],[9002,103,10],[9844,114,5],[10380,120,1],[10473,122,3],[10775,126,6],[12544,134,3],[12805,138,5],[13622,145,7],[14326,153,1],[14432,155,9],[15256,165,4],[15726,170,1],[15813,172,6],[16420,179,8],[17059,188,4],[17488,193,6],[18158,200,1],[18238,202,9],[19012,212,3],[19330,216,1],[19407,218,4]]],[21044,"A semente brota e cresce sem que o homem saiba explicar como. Primeiro aparece a planta, depois a espiga, e por fim o grão cheio na espiga. Jesus dá tempo a cada etapa. O crescimento acontece enquanto o semeador segue seus dias.",[[21044,0,1],[21135,2,7],[21855,10,5],[22400,16,1],[22505,18,6],[23065,25,3],[23397,29,3],[23557,33,1],[23655,35,5],[24029,41,5],[24578,47,8],[25275,56,4],[26884,62,8],[27514,71,7],[28206,79,1],[28300,81,6],[29196,89,6],[29786,96,1],[29854,98,6],[30843,106,1],[30936,108,3],[31182,112,3],[31539,116,1],[31625,118,4],[31940,123,5],[32447,129,2],[32613,132,6],[34401,140,5],[35008,146,2],[35206,149,5],[35739,155,1],[35838,157,4],[36278,162,5],[37994,169,1],[38079,171,11],[38978,183,8],[39778,192,8],[40368,201,1],[40430,203,8],[41181,212,5],[41646,218,4],[41997,223,4]]],[43689,"Quando o grão amadurece, o agricultor pega a foice, pois chegou a colheita. A parábola abre espaço para confiar no crescimento que ainda está escondido. Quem semeia pode reconhecer a hora de colher, embora o processo inteiro escape ao seu controle.",[[43689,0,6],[44093,7,1],[44181,9,4],[44512,14,9],[45621,25,1],[45725,27,10],[46555,38,4],[46984,43,1],[47077,45,5],[48051,52,4],[48504,57,6],[48937,64,1],[49010,66,8],[50901,76,1],[50993,78,8],[51763,87,4],[52174,92,6],[52886,99,4],[53197,104,7],[53873,112,2],[54053,115,11],[54932,127,3],[55102,131,5],[55526,137,4],[55877,142,9],[57888,153,4],[58166,158,6],[58711,165,4],[59111,170,10],[59927,181,1],[60028,183,4],[60385,188,2],[60545,191,6],[61405,199,6],[61911,206,1],[61985,208,8],[62755,217,7],[63300,225,6],[63980,232,2],[64111,235,3],[64414,239,8]]]]},"o-joio-e-o-trigo":{"audio":"audio/o-joio-e-o-trigo.mp3?v=1d95252ce07f","quadros":[[0,"Um homem semeia trigo em seu campo. Enquanto todos dormem, um inimigo espalha joio no mesmo terreno e vai embora. As duas plantas crescem lado a lado. Quando o trigo começa a produzir espigas, os servos finalmente percebem o joio.",[[109,0,2],[300,3,5],[661,9,6],[1209,16,5],[1744,22,2],[1875,25,3],[2179,29,5],[3852,36,8],[4491,45,5],[5003,51,6],[5802,59,2],[5998,62,7],[6654,70,7],[7289,78,4],[7688,83,2],[7842,86,5],[8369,92,7],[9015,100,1],[9119,102,3],[9392,106,6],[11081,114,2],[11291,117,4],[11712,122,7],[12342,130,7],[12828,138,4],[13246,143,1],[13333,145,4],[14944,151,6],[15343,158,1],[15431,160,5],[15945,166,6],[16586,173,1],[16666,175,8],[17334,184,7],[18386,193,2],[18542,196,6],[19089,203,10],[19914,214,8],[20700,223,1],[20787,225,4]]],[22352,"Os servos perguntam de onde vieram as ervas e se devem arrancá-las. O dono reconhece o trabalho de um inimigo, mas manda esperar. Se os servos arrancarem o joio agora, podem arrancar o trigo junto. As duas plantas ficam no campo até a colheita.",[[22352,0,2],[22495,3,6],[23048,10,9],[23833,20,2],[24024,23,4],[24357,28,6],[24866,35,2],[25076,38,5],[25614,44,1],[25683,46,2],[25894,49,5],[26343,55,11],[28310,68,1],[28412,70,4],[28791,75,9],[29622,85,1],[29696,87,8],[30339,96,2],[30481,99,2],[30645,102,7],[31648,111,3],[31972,115,5],[32386,121,7],[34292,130,2],[34501,133,2],[34649,136,6],[35164,143,10],[35850,154,1],[35937,156,4],[36358,161,5],[37215,168,5],[37705,174,8],[38268,183,1],[38361,185,5],[38878,191,5],[40540,198,2],[40751,201,4],[41172,206,7],[41820,214,5],[42253,220,2],[42417,223,5],[42953,229,3],[43285,233,1],[43361,235,8]]],[45242,"Na colheita, os encarregados separam o joio para queimar e recolhem o trigo no celeiro. Depois, em particular, Jesus diz aos discípulos que o campo é o mundo e a colheita é o fim dos tempos. A separação cabe aos responsáveis que o Filho do Homem enviar.",[[45242,0,2],[45405,3,8],[46467,13,2],[46672,16,12],[47713,29,7],[48265,37,1],[48352,39,4],[48767,44,4],[49076,49,7],[49621,57,1],[49728,59,8],[50414,68,1],[50502,70,5],[50990,76,2],[51132,79,7],[52922,88,6],[53968,96,2],[54142,99,10],[55345,111,5],[55925,117,3],[56264,121,3],[56475,125,10],[57405,136,3],[57549,140,1],[57643,142,5],[58164,148,1],[58306,150,1],[58374,152,5],[58905,158,1],[59041,160,1],[59135,162,8],[59813,171,1],[59954,173,1],[60059,175,3],[60429,179,3],[60735,183,6],[62528,191,1],[62620,193,9],[63550,203,4],[63950,208,3],[64188,212,12],[65400,225,3],[65540,229,1],[65620,231,5],[66093,237,2],[66279,240,5],[66650,246,6]]]]},"o-grao-de-mostarda":{"audio":"audio/o-grao-de-mostarda.mp3?v=39e5ad98669a","quadros":[[0,"Jesus pede aos ouvintes que imaginem um grão de mostarda. Na mão de quem vai semear, parece quase insignificante. O homem o coloca na terra. É com essa coisa pequena, familiar a quem cultivava o chão, que Jesus começa a descrever o Reino.",[[112,0,5],[719,6,4],[1094,11,3],[1319,15,8],[2109,24,3],[2271,28,8],[2918,37,2],[3116,40,4],[3450,45,2],[3597,48,8],[5573,58,2],[5728,61,3],[6026,65,2],[6184,68,4],[6489,73,3],[6750,77,6],[7706,85,6],[8336,92,5],[8826,98,14],[11288,114,1],[11416,116,5],[11844,122,1],[11918,124,6],[12536,131,2],[12722,134,5],[14362,141,1],[14446,143,3],[14726,147,4],[15106,152,5],[15586,158,7],[16574,167,8],[17263,176,1],[17376,178,4],[17666,183,9],[18416,193,1],[18490,195,4],[19205,201,3],[19422,205,5],[20015,211,6],[20685,218,1],[20759,220,9],[21517,230,1],[21597,232,5]]],[23282,"Da semente escondida surge uma planta que cresce muito além de seu primeiro tamanho. O que cabia entre os dedos abre ramos largos. A comparação de Jesus se apoia na mudança de escala entre o grão discreto e a planta que se torna visível.",[[23282,0,2],[23441,3,7],[24160,11,9],[25007,21,5],[25561,27,3],[25785,31,6],[26310,38,3],[26501,42,6],[27035,49,5],[27542,55,4],[27912,60,2],[28047,63,3],[28328,67,8],[28955,76,7],[30723,85,1],[30808,87,3],[30988,91,5],[31467,97,5],[31834,103,2],[32026,106,5],[32557,112,4],[32975,117,5],[33464,123,6],[35321,131,1],[35413,133,10],[36300,144,2],[36450,147,5],[37042,153,2],[37202,156,5],[37704,162,2],[37848,165,7],[38492,173,2],[38647,176,6],[39241,183,5],[39625,189,1],[39711,191,4],[40044,196,8],[40881,205,1],[41026,207,1],[41121,209,6],[41641,216,3],[41811,220,2],[42031,223,5],[42531,229,7]]],[44395,"A planta de mostarda está tão desenvolvida que as aves podem abrigar-se em seus ramos. Quem ouve a parábola vê o Reino pela distância entre essas duas imagens, o grão na terra e os galhos cheios de vida. O início pequeno dá lugar a um alcance surpreendente.",[[44395,0,1],[44505,2,6],[45032,9,2],[45181,12,8],[45965,21,4],[46335,26,3],[46634,30,12],[47700,43,3],[47847,47,2],[48054,50,4],[48543,55,5],[49004,61,10],[49853,72,2],[49989,75,4],[50385,80,5],[52183,87,4],[52492,92,4],[52856,97,1],[52929,99,8],[53701,108,2],[53901,111,1],[53987,113,5],[54481,119,4],[54811,124,9],[55710,134,5],[56120,140,5],[56577,146,4],[56940,151,7],[58071,160,1],[58190,162,4],[58503,167,2],[58700,170,5],[59201,176,1],[59307,178,2],[59500,181,6],[60006,188,6],[60525,195,2],[60689,198,4],[62259,204,1],[62359,206,6],[62940,213,7],[63498,221,2],[63696,224,5],[64124,230,1],[64199,232,2],[64360,235,7],[65029,243,13]]]]},"o-fermento":{"audio":"audio/o-fermento.mp3?v=fa609fb047cb","quadros":[[0,"Jesus faz outra comparação para falar do Reino dos céus. Uma mulher toma um pouco de fermento para preparar uma grande porção de farinha. Aos olhos de quem observa os ingredientes separados, a pequena porção mal chama a atenção perto de toda a farinha.",[[112,0,5],[719,6,3],[1069,10,5],[1495,16,10],[2409,27,4],[2692,32,5],[3195,38,2],[3330,41,5],[3810,47,3],[4089,51,4],[5680,57,3],[5883,61,6],[6384,68,4],[6756,73,2],[6936,76,5],[7471,82,2],[7633,85,8],[8376,94,4],[8693,99,8],[9345,108,3],[9583,112,6],[10084,119,6],[10683,126,2],[10831,129,7],[12555,138,3],[12865,142,5],[13274,148,2],[13425,151,4],[13719,156,7],[14469,164,2],[14649,167,12],[15649,180,9],[16924,191,1],[17029,193,7],[17589,201,6],[18219,208,3],[18507,212,5],[18977,218,1],[19058,220,7],[19705,228,5],[20223,234,2],[20398,237,4],[20859,242,1],[20921,244,7]]],[22633,"A mulher incorpora o fermento na farinha. À medida que ela trabalha a massa, o fermento deixa de aparecer por si só. A ação ocorre por dentro, espalhando-se naquilo que ela preparou. A parábola acompanha esse processo até o resultado poder ser reconhecido.",[[22633,0,1],[22718,2,6],[23208,9,9],[23900,19,1],[23961,21,8],[24665,30,2],[24820,33,7],[26525,42,1],[26617,44,6],[27228,51,3],[27457,55,3],[27717,59,8],[28336,68,1],[28423,70,5],[29273,77,1],[29365,79,8],[30108,88,5],[30632,94,2],[30809,97,8],[31504,106,3],[31743,110,2],[32091,113,2],[33529,117,1],[33620,119,4],[34070,124,6],[34615,131,3],[34870,135,6],[35705,143,13],[36708,157,7],[37281,165,3],[37455,169,3],[37710,173,8],[39556,183,1],[39648,185,8],[40417,194,9],[41128,204,4],[41458,209,8],[42282,218,3],[42607,222,1],[42687,224,9],[43589,234,5],[44047,240,3],[44330,244,11]]],[46522,"Com o tempo, toda a massa fermenta. Jesus escolhe uma tarefa familiar da casa para mostrar como o Reino pode transformar o conjunto a partir de uma presença discreta. O que parecia pequeno em relação à farinha passa a afetar toda a preparação.",[[46522,0,3],[46783,4,1],[46876,6,5],[47732,13,4],[48207,18,1],[48301,20,5],[48741,26,8],[50559,36,5],[51137,42,7],[51766,50,3],[51987,54,6],[52567,61,8],[53268,70,2],[53447,73,4],[53975,78,4],[54273,83,7],[54909,91,4],[55296,96,1],[55384,98,5],[55879,104,4],[56309,109,11],[57149,121,1],[57236,123,8],[58002,132,1],[58082,134,6],[58651,141,2],[58804,144,3],[59025,148,8],[59765,157,8],[61729,167,1],[61811,169,3],[61981,173,7],[62605,181,7],[63169,189,2],[63312,192,7],[64003,200,1],[64110,202,7],[64703,210,5],[65260,216,1],[65341,218,6],[65952,225,4],[66402,230,1],[66482,232,10]]]]},"o-tesouro-escondido":{"audio":"audio/o-tesouro-escondido.mp3?v=c850092e1398","quadros":[[0,"Jesus compara o Reino dos céus a um tesouro escondido num campo. Um homem encontra o que estava enterrado. O terreno, que podia parecer comum para quem passasse por ali, agora guarda para ele uma descoberta que muda o valor de tudo ao redor.",[[112,0,5],[719,6,7],[1332,14,1],[1413,16,5],[1908,22,3],[2132,26,4],[2482,31,1],[2556,33,2],[2711,36,7],[3384,44,9],[4198,54,3],[4421,58,5],[6078,65,2],[6269,68,5],[6648,74,8],[7311,83,1],[7386,85,3],[7541,89,6],[8108,96,9],[10015,107,1],[10117,109,7],[11084,118,3],[11282,122,5],[11765,128,7],[12387,136,5],[12884,142,4],[13197,147,4],[13478,152,8],[14062,161,3],[14293,165,3],[14962,170,5],[15506,176,6],[16086,183,4],[16421,188,3],[16706,192,3],[16916,196,10],[17876,207,3],[18052,211,4],[18517,216,1],[18590,218,5],[19056,224,2],[19266,227,4],[19682,232,2],[19831,235,5]]],[21578,"O homem volta a esconder o tesouro no mesmo lugar. A breve história destaca o que ele sente ao perceber o valor daquilo que encontrou. É por causa da alegria que ele se põe em movimento e decide o que fazer com todos os seus bens.",[[21578,0,1],[21706,2,5],[22093,8,5],[22656,14,1],[22724,16,8],[23356,25,1],[23430,27,7],[24127,35,2],[24288,38,5],[24758,44,5],[26500,51,1],[26620,53,5],[27113,59,8],[27693,68,7],[28400,76,1],[28473,78,3],[28700,82,3],[28945,86,5],[29445,92,2],[29571,95,8],[30247,104,1],[30322,106,5],[30780,112,7],[31360,120,3],[31558,124,9],[33410,135,1],[33494,137,3],[33754,141,5],[34270,147,2],[34449,150,7],[35058,158,3],[35238,162,3],[35424,166,2],[35629,169,3],[35934,173,2],[36072,176,9],[36890,186,1],[36993,188,6],[37613,195,1],[37687,197,3],[37847,201,5],[38313,207,3],[38593,211,5],[39100,217,2],[39249,220,4],[39642,225,4]]],[41285,"Ele vende tudo o que possui e compra o campo. A perda de seus bens, vista de fora, parece enorme. A alegria da descoberta explica sua escolha. Jesus usa essa decisão para mostrar o que o Reino passa a valer aos olhos de quem o reconhece.",[[41285,0,3],[41531,4,5],[42004,10,4],[42469,15,1],[42550,17,3],[42718,21,6],[43249,28,1],[43355,30,6],[43895,37,1],[43982,39,5],[45641,46,1],[45743,48,5],[46248,54,2],[46384,57,4],[46812,62,4],[47633,68,5],[48190,74,2],[48350,77,4],[49167,83,6],[49822,90,6],[51544,98,1],[51636,100,7],[52252,108,2],[52415,111,10],[53303,122,7],[54025,130,3],[54344,134,7],[56138,143,5],[56745,149,3],[57134,153,4],[57455,158,7],[58165,166,4],[58442,171,7],[59045,179,1],[59131,181,3],[59315,185,1],[59399,187,5],[59896,193,5],[60454,199,1],[60528,201,5],[60934,207,3],[61214,211,5],[61623,217,2],[61773,220,4],[62063,225,1],[62124,227,9]]]]},"a-perola-de-grande-valor":{"audio":"audio/a-perola-de-grande-valor.mp3?v=5b6d85ae34c5","quadros":[[0,"Desta vez, Jesus apresenta um mercador que procura pérolas finas. Ele sabe que as melhores peças merecem ser buscadas. A imagem começa com uma procura deliberada. Entre muitas pérolas, o comerciante quer reconhecer aquela cujo valor justificará uma decisão diferente.",[[105,0,5],[629,6,3],[1412,11,5],[2009,17,9],[2767,27,2],[2934,30,8],[3639,39,3],[3819,43,7],[4469,51,7],[5158,59,5],[6933,66,3],[7160,70,4],[7638,75,3],[7774,79,2],[7960,82,8],[8647,91,5],[9207,97,7],[9855,105,3],[10128,109,8],[12092,119,1],[12184,121,6],[12815,128,6],[13454,135,3],[13715,139,3],[13933,143,7],[14573,151,10],[16467,163,5],[16844,169,6],[17448,176,7],[18515,185,1],[18608,187,11],[19667,199,4],[19971,204,10],[20805,215,6],[21337,222,4],[21777,227,5],[22227,233,11],[23119,245,3],[23339,249,7],[23996,257,9]]],[25982,"A busca termina quando o mercador encontra uma pérola de valor excepcional. Ele avalia o que tem diante de si à luz de tudo o que conhece. Nesse momento, concentra a atenção em uma única peça e decide reorganizar seus negócios em torno dela.",[[25982,0,1],[26102,2,5],[26684,8,7],[27282,16,6],[27668,23,1],[27730,25,8],[28421,34,8],[29090,43,3],[29310,47,6],[29914,54,2],[30074,57,5],[30497,63,11],[32622,76,3],[32869,80,6],[33416,87,1],[33509,89,3],[33684,93,3],[33958,97,6],[34507,104,2],[34662,107,2],[34914,110,1],[34996,112,3],[35299,116,2],[35466,119,4],[35919,124,1],[35993,126,3],[36173,130,7],[38014,139,5],[38416,145,7],[39424,154,9],[40215,164,1],[40304,166,7],[40965,174,2],[41135,177,3],[41365,181,5],[41825,187,4],[42457,192,1],[42563,194,6],[43158,201,11],[44115,213,4],[44530,218,8],[45390,227,2],[45574,230,5],[46085,236,4]]],[47625,"O mercador vende tudo o que possui para adquirir a pérola. Jesus apresenta o Reino dos céus pela perspectiva de alguém que sabe avaliar o que encontra. Uma vez reconhecido seu valor, o homem assume o custo inteiro de sua escolha.",[[47625,0,1],[47696,2,8],[48383,11,5],[48856,17,4],[49319,22,1],[49399,24,3],[49559,28,6],[50086,35,4],[50368,40,8],[50950,49,1],[51062,51,6],[52841,59,5],[53419,65,9],[54197,75,1],[54286,77,5],[54778,83,3],[55001,87,4],[55370,92,4],[55709,97,11],[56787,109,2],[56939,112,6],[57385,119,3],[57551,123,4],[58017,128,7],[58593,136,1],[58680,138,3],[58890,142,8],[60705,152,3],[60949,156,3],[61242,160,11],[62219,172,3],[62498,176,5],[63359,183,1],[63501,185,5],[63877,191,6],[64404,198,1],[64492,200,5],[65056,206,7],[65619,214,2],[65773,217,3],[66061,221,7]]]]},"a-rede-de-pesca":{"audio":"audio/a-rede-de-pesca.mp3?v=ce258f37e860","quadros":[[0,"Jesus compara o Reino dos céus a uma rede lançada ao mar. A rede se enche de peixes de toda espécie. Enquanto está na água, tudo permanece junto. Os pescadores esperam que a pesca esteja completa para puxar a rede até a praia.",[[112,0,5],[719,6,7],[1332,14,1],[1413,16,5],[1908,22,3],[2132,26,4],[2481,31,1],[2555,33,3],[2770,37,4],[3252,42,7],[3892,50,2],[4049,53,4],[5617,58,1],[5719,60,4],[6189,65,2],[6437,68,5],[6809,74,2],[6977,77,6],[7605,84,2],[7779,87,4],[8183,92,7],[10100,101,8],[10714,110,4],[11061,115,2],[11251,118,4],[12014,124,4],[12465,129,9],[13320,139,5],[14994,146,2],[15167,149,10],[16084,160,7],[16714,168,3],[16877,172,1],[16970,174,5],[17537,180,6],[18114,187,8],[18864,196,4],[19169,201,5],[19682,207,1],[19793,209,4],[20290,214,3],[20628,218,1],[20723,220,5]]],[22348,"Na areia, os pescadores se sentam diante da rede. Agora podem examinar o que trouxeram. Colocam nos recipientes os peixes que servem e descartam os que não servem. A triagem vem depois de toda a captura, quando a rede já está fora da água.",[[22348,0,2],[22530,3,5],[23346,10,2],[23569,13,10],[24539,24,2],[24709,27,6],[25211,34,6],[25797,41,2],[25964,44,4],[27579,50,5],[28091,56,5],[28591,62,8],[29256,71,1],[29349,73,3],[29519,77,9],[31508,88,7],[32216,96,3],[32458,100,11],[33525,112,2],[33729,115,6],[34389,122,3],[34542,126,6],[35257,133,1],[35365,135,9],[36107,145,2],[36281,148,3],[36436,152,3],[36667,156,6],[38458,164,1],[38549,166,7],[39243,174,3],[39519,178,6],[40073,185,2],[40240,188,4],[40695,193,1],[40776,195,7],[41793,204,6],[42192,211,1],[42279,213,4],[42760,218,2],[42965,221,4],[43344,226,4],[43819,231,2],[44018,234,4]]],[45564,"Jesus associa o momento da triagem ao fim dos tempos. Assim como a rede cheia reúne espécies diferentes, a coleta vem antes da separação. Na explicação, a tarefa de distinguir os maus dos justos fica com os anjos. A imagem termina com a seriedade do juízo.",[[45564,0,5],[46142,6,7],[46815,14,1],[46884,16,7],[47516,24,2],[47672,27,7],[48383,35,2],[48520,38,3],[48885,42,3],[49189,46,6],[50984,54,5],[51456,60,4],[51815,65,1],[51903,67,4],[52380,72,5],[52875,78,5],[53318,84,8],[54088,93,10],[55370,105,1],[55475,107,6],[56169,114,3],[56448,118,5],[56964,124,2],[57129,127,9],[59185,138,2],[59341,141,10],[60627,153,1],[60732,155,6],[61349,162,2],[61509,165,10],[62239,176,2],[62413,179,4],[62819,184,3],[63058,188,6],[63786,195,4],[64168,200,3],[64422,204,2],[64620,207,5],[66323,214,1],[66415,216,6],[67065,223,7],[67642,231,3],[67895,235,1],[67972,237,9],[68812,247,2],[68949,250,5]]]]},"a-lampada-acesa":{"audio":"audio/a-lampada-acesa.mp3?v=71891b134d42","quadros":[[0,"Jesus convida os ouvintes a pensar numa lâmpada acesa dentro de casa. Uma chama pequena pode iluminar os que estão ali. Cobrir a lâmpada com um recipiente ou colocá-la debaixo da cama impediria que a luz cumprisse sua função.",[[112,0,5],[719,6,7],[1221,14,2],[1369,17,8],[2121,26,1],[2208,28,6],[2761,35,4],[3068,40,7],[3708,48,5],[4369,54,6],[4861,61,2],[5044,64,4],[6697,70,3],[6942,74,5],[7412,80,7],[7994,88,4],[8433,93,8],[9072,102,2],[9261,105,3],[9411,109,5],[9834,115,3],[11315,120,6],[11825,127,1],[11935,129,7],[12580,137,3],[12835,141,2],[12995,144,10],[14024,155,2],[14202,158,9],[14854,168,7],[15564,176,2],[15744,179,4],[16119,184,9],[16793,194,3],[16953,198,1],[17039,200,3],[17399,204,9],[18023,214,3],[18301,218,6]]],[20051,"Colocada no suporte, a lâmpada ilumina o cômodo para todos. Em Marcos e em Lucas, Jesus liga essa imagem ao que hoje está escondido e acabará vindo à luz. Ouvir com atenção faz parte da resposta de quem recebe uma palavra destinada a ser conhecida.",[[20051,0,8],[20840,9,2],[20984,12,7],[22176,21,1],[22282,23,7],[22922,31,7],[23492,39,1],[23578,41,6],[24102,48,4],[24454,53,5],[26248,60,2],[26410,63,6],[27049,70,1],[27155,72,2],[27311,75,5],[28212,82,5],[28840,88,4],[29257,93,4],[29629,98,6],[30251,105,2],[30401,108,3],[30633,112,4],[31030,117,4],[31384,122,9],[32249,132,1],[32393,134,7],[32981,142,5],[33421,148,1],[33595,150,3],[35121,155,5],[35579,161,3],[35841,165,7],[36477,173,3],[36837,177,5],[37385,183,2],[37535,186,8],[38409,195,2],[38564,198,4],[38848,203,6],[39491,210,3],[39702,214,7],[40388,222,9],[41248,232,1],[41329,234,3],[41634,238,9]]],[43621,"No Sermão do Monte, a chama no suporte ajuda a explicar o que significa ser luz do mundo. Jesus chama os discípulos a deixar que as pessoas vejam suas boas obras. Assim, o que fazem aponta para o Pai que está nos céus.",[[43621,0,2],[43759,3,6],[44312,10,2],[44449,13,5],[45290,20,1],[45389,22,5],[45843,28,2],[45980,31,7],[46803,39,5],[47412,45,1],[47481,47,8],[48171,56,1],[48258,58,3],[48420,62,9],[49361,72,3],[49679,76,3],[50007,80,2],[50163,83,5],[51778,90,5],[52385,96,5],[52775,102,2],[52905,105,10],[53825,116,1],[53910,118,6],[54455,125,3],[54615,129,2],[54793,132,7],[55443,140,5],[55899,146,4],[56314,151,4],[56764,156,5],[58510,163,5],[59368,170,1],[59460,172,3],[59625,176,5],[60199,182,6],[60790,189,4],[61070,194,1],[61144,196,3],[61480,200,3],[61636,204,4],[62000,209,3],[62268,213,4]]]]},"a-roupa-remendada-e-o-vinho-novo":{"audio":"audio/a-roupa-remendada-e-o-vinho-novo.mp3?v=a5ae8e44e23d","quadros":[[0,"Perguntam a Jesus por que seus discípulos se comportam de modo diferente quando outros jejuam. Ele fala primeiro da alegria dos convidados enquanto o noivo está presente. Depois recorre a uma roupa velha. Um pedaço de tecido novo, ao repuxar, pode aumentar o rasgo.",[[107,0,9],[917,10,1],[992,12,5],[1589,18,3],[1829,22,3],[1999,26,4],[2362,31,10],[3296,42,2],[3483,45,9],[4181,55,2],[4334,58,4],[4733,63,9],[5538,73,6],[6008,80,6],[6516,87,6],[8249,95,3],[8476,99,4],[8970,104,8],[9608,113,2],[9780,116,7],[10391,124,3],[10651,128,10],[11552,139,8],[12167,148,1],[12260,150,5],[12763,156,4],[13116,161,8],[15077,171,6],[15663,178,7],[16267,186,1],[16340,188,3],[16555,192,5],[17121,198,5],[18742,205,2],[18897,208,6],[19553,215,2],[19729,218,6],[20331,225,4],[21193,231,2],[21365,234,7],[22489,243,4],[22921,248,8],[23537,257,1],[23624,259,5]]],[25375,"Jesus passa da roupa ao vinho. O vinho novo precisa de um recipiente que aguente sua expansão. Se alguém o puser num odre envelhecido, o couro pode romper. O vinho se derrama, e a vasilha que deveria preservá-lo também se perde.",[[25375,0,5],[25983,6,5],[26470,12,2],[26632,15,5],[27174,21,2],[27337,24,5],[28945,31,1],[29045,33,5],[29440,39,4],[29904,44,7],[30604,52,2],[30745,55,2],[30905,58,10],[31870,69,3],[32054,73,7],[32536,81,3],[32834,85,8],[34742,95,2],[34957,98,6],[35379,105,1],[35458,107,5],[35968,113,3],[36223,117,4],[36588,122,11],[37855,135,1],[37968,137,5],[38420,143,4],[38836,148,6],[40640,156,1],[40740,158,5],[41104,164,2],[41310,167,7],[42092,176,1],[42192,178,1],[42266,180,7],[42900,188,3],[43073,192,7],[43604,200,11],[44423,212,6],[44904,219,2],[45111,222,5]]],[46829,"O vinho novo vai em odres novos, capazes de contê-lo. Em Mateus, assim se conservam tanto o vinho quanto o recipiente. As duas imagens convidam quem fez a pergunta a perceber que a presença de Jesus muda as circunstâncias às quais suas práticas precisam responder.",[[46829,0,1],[46929,2,5],[47323,8,4],[47802,13,3],[48073,17,2],[48238,20,5],[48641,26,5],[49636,33,7],[50406,41,2],[50567,44,8],[52294,54,2],[52441,57,6],[53486,65,5],[53944,71,2],[54148,74,9],[55078,84,5],[55560,90,1],[55647,92,5],[56061,98,6],[56548,105,1],[56608,107,10],[58759,119,2],[58972,122,4],[59341,127,7],[60059,135,8],[60732,144,4],[60997,149,3],[61337,153,1],[61430,155,8],[62175,164,1],[62250,166,8],[62950,175,3],[63111,179,1],[63186,181,8],[63938,190,2],[64101,193,5],[64701,199,4],[65167,204,2],[65314,207,14],[66480,222,2],[66709,225,5],[67199,231,4],[67618,236,8],[68410,245,8],[69173,254,9]]]]},"o-dono-da-casa-e-seu-tesouro":{"audio":"audio/o-dono-da-casa-e-seu-tesouro.mp3?v=9ae826459705","quadros":[[0,"Depois de ensinar por parábolas, Jesus pergunta aos discípulos se compreenderam. Eles dizem que sim. A resposta leva a uma última imagem. Jesus pede que imaginem o dono de uma casa diante do depósito onde guarda o que lhe foi confiado.",[[103,0,6],[648,7,2],[828,10,7],[1424,18,3],[1666,22,9],[2804,33,5],[3429,39,8],[4177,48,3],[4375,52,10],[5338,63,2],[5518,66,13],[7594,81,4],[7914,86,5],[8392,92,3],[8559,96,3],[10097,101,1],[10161,103,8],[11057,112,4],[11515,117,1],[11590,119,3],[11776,123,6],[12344,130,6],[14135,138,5],[14742,144,4],[15192,149,3],[15391,153,8],[16068,162,1],[16154,164,4],[16536,169,2],[16692,172,3],[16922,176,4],[17415,181,6],[17982,188,2],[18125,191,8],[19012,200,4],[19362,205,6],[19941,212,1],[20015,214,3],[20177,218,3],[20326,222,3],[20620,226,8]]],[22568,"Ao abrir seu depósito, o dono encontra bens antigos e novos. As coisas já guardadas continuam ao alcance da sua mão. O valor do depósito aparece quando ele tira dali o que precisa, recorrendo ao que recebeu antes e ao que adquiriu depois.",[[22568,0,2],[22740,3,5],[23169,9,3],[23464,13,8],[24698,23,1],[24810,25,4],[25199,30,8],[25844,39,4],[26272,44,7],[26991,52,1],[27060,54,5],[28853,61,2],[29080,64,6],[29643,71,2],[29838,74,9],[30693,84,9],[31426,94,2],[31595,97,7],[32259,105,2],[32433,108,3],[32774,112,3],[34194,117,1],[34275,119,5],[34742,125,2],[34878,128,8],[35762,137,7],[36444,145,6],[36851,152,3],[37069,156,4],[37503,161,4],[37874,166,1],[37948,168,3],[38115,172,7],[39224,181,10],[39983,192,2],[40133,195,3],[40293,199,7],[41013,207,5],[41544,213,1],[41656,215,2],[41813,218,3],[41973,222,8],[42575,231,6]]],[44426,"Jesus compara esse dono de casa ao escriba instruído no Reino dos céus. O mestre capaz de compreender o ensinamento dispõe de coisas antigas e novas para partilhar. A imagem encerra uma sequência de parábolas sobre ouvir, compreender e reconhecer o que Deus está fazendo.",[[44426,0,5],[45034,6,7],[45659,14,4],[45994,19,4],[46371,24,2],[46550,27,4],[47057,32,2],[47227,35,7],[47890,43,9],[48642,53,2],[48792,56,5],[49266,62,3],[49523,66,4],[51126,72,1],[51197,74,6],[51788,81,5],[52359,87,2],[52517,90,11],[53291,102,1],[53396,104,11],[54338,116,6],[54896,123,2],[55061,126,6],[55676,133,7],[56394,141,1],[56486,143,5],[57083,149,4],[57396,154,9],[59361,165,1],[59461,167,6],[60094,174,7],[60681,182,3],[60888,186,9],[61639,196,2],[61795,199,9],[62550,209,5],[62985,215,5],[63821,222,11],[64635,234,1],[64740,236,10],[65563,247,1],[65649,249,3],[65829,253,4],[66214,258,4],[66579,263,7]]]]},"a-figueira-que-anuncia-a-estacao":{"audio":"audio/a-figueira-que-anuncia-a-estacao.mp3?v=c94afac93b9b","quadros":[[0,"Jesus fala aos discípulos sobre acontecimentos que deverão aprender a reconhecer. Para ensinar a observar, aponta para a figueira. Ao longo do ano, ela muda diante de quem passa. Seus galhos, ainda sem folhas, oferecem o primeiro quadro de uma mudança que pode ser notada.",[[112,0,5],[719,6,4],[1155,11,3],[1354,15,10],[2279,26,5],[2709,32,14],[3970,47,3],[4123,51,7],[4668,59,8],[5247,68,1],[5328,70,10],[7518,82,4],[7920,87,7],[8509,95,1],[8588,97,8],[9770,107,6],[10380,114,4],[10673,119,1],[10735,121,8],[12541,131,2],[12723,134,5],[13140,140,2],[13328,143,3],[14017,148,3],[14293,152,4],[14795,157,6],[15353,164,2],[15513,167,4],[15809,172,5],[17470,179,4],[17879,184,6],[18758,192,5],[19227,198,3],[19560,202,6],[20572,210,8],[21396,219,1],[21470,221,8],[22092,230,6],[22648,237,2],[22801,240,3],[22986,244,7],[23643,252,3],[23829,256,4],[24216,261,3],[24517,265,6]]],[26219,"Quando os ramos ficam tenros e as folhas começam a brotar, a árvore dá indícios de que o verão está perto. Em Lucas, Jesus convida a reparar também nas outras árvores. Quem vê a brotação pode reconhecer a proximidade da estação.",[[26219,0,6],[26608,7,2],[26807,10,5],[27312,16,5],[27794,22,6],[28228,29,1],[28330,31,2],[28571,34,6],[29090,41,7],[29779,49,1],[29854,51,6],[30800,59,1],[30938,61,6],[31492,68,2],[31687,71,8],[32446,80,2],[32613,83,3],[32773,87,1],[32841,89,5],[33273,95,4],[33623,100,5],[35408,107,2],[35570,110,5],[36504,117,5],[37131,123,7],[37661,131,1],[37724,133,7],[38409,141,6],[38920,148,3],[39199,152,6],[39759,159,7],[41582,168,4],[41886,173,2],[42077,176,1],[42152,178,8],[42924,187,4],[43316,192,10],[44133,203,1],[44220,205,11],[45209,217,2],[45370,220,7]]],[47246,"Jesus aplica a observação da figueira aos sinais que acaba de descrever. Em Lucas, quando os discípulos virem essas coisas acontecer, poderão saber que o Reino de Deus se aproxima. A árvore familiar ajuda a entender como reconhecer uma mudança por aquilo que já se torna visível.",[[47246,0,5],[47824,6,6],[48480,13,1],[48564,15,10],[49545,26,2],[49700,29,8],[50352,38,3],[50562,42,6],[51140,49,3],[51285,53,5],[51824,59,2],[51985,62,9],[54101,73,2],[54260,76,5],[55182,83,6],[55611,90,2],[55742,93,10],[56652,104,5],[57010,110,5],[57482,116,6],[58071,123,9],[59299,134,7],[59888,142,5],[60381,148,3],[60543,152,1],[60630,154,5],[61116,160,2],[61272,163,4],[61670,168,2],[61840,171,8],[63757,181,1],[63885,183,6],[64385,190,8],[65067,199,5],[65678,205,1],[65747,207,8],[66343,216,4],[66701,221,10],[67529,232,3],[67722,236,7],[68384,244,3],[68617,248,6],[69156,255,3],[69338,259,2],[69542,262,2],[69758,265,5],[70266,271,7]]]]},"o-bom-samaritano":{"audio":"audio/o-bom-samaritano.mp3?v=c94415591ddd","quadros":[[0,"Um intérprete da Lei pergunta a Jesus quem é seu próximo. Jesus conta que um homem descia de Jerusalém para Jericó quando assaltantes o deixaram ferido. Passaram por ali um sacerdote e um levita. Ambos viram o homem à margem e seguiram pelo outro lado.",[[107,0,2],[278,3,10],[1188,14,2],[1349,17,3],[1640,21,8],[2383,30,1],[2459,32,5],[3049,38,4],[3349,43,1],[3437,45,3],[3730,49,7],[5632,58,5],[6239,64,5],[6693,70,3],[6840,74,2],[7000,77,5],[7379,83,6],[7860,90,2],[8013,93,9],[8816,103,4],[9109,108,6],[9698,115,6],[10099,122,11],[11066,134,1],[11153,136,8],[11834,145,6],[13549,153,8],[14255,162,3],[14479,166,3],[14761,170,2],[14904,173,9],[15980,183,1],[16122,185,2],[16282,188,6],[18069,196,5],[18536,202,5],[18957,208,1],[19056,210,5],[19422,216,1],[19526,218,6],[20192,225,1],[20267,227,8],[20878,236,4],[21265,241,5],[21703,247,4]]],[23295,"Um samaritano veio pela mesma estrada e se compadeceu. Aproximou-se, tratou os ferimentos com azeite e vinho e fez curativos. Depois pôs o homem sobre seu próprio animal. O ferido ainda precisava de abrigo e tempo para se recuperar.",[[23295,0,2],[23439,3,10],[24399,14,4],[24781,19,4],[25117,24,5],[25630,30,7],[26365,38,1],[26433,40,2],[26638,43,10],[28625,55,12],[30014,69,6],[30534,76,2],[30707,79,10],[31625,90,3],[31865,94,6],[32556,101,1],[32656,103,5],[33098,109,1],[33203,111,3],[33563,115,9],[35526,126,6],[36133,133,3],[36518,137,1],[36616,139,5],[36986,145,5],[37431,151,3],[37712,155,7],[38360,163,6],[40069,171,1],[40150,173,6],[40743,180,5],[41200,186,9],[42086,196,2],[42258,199,6],[42882,206,1],[42989,208,5],[43501,214,4],[43793,219,2],[43991,222,9]]],[46092,"Na hospedaria, o samaritano cuida do ferido, paga ao hospedeiro e promete cobrir o que faltar na volta. Jesus pergunta qual viajante se tornou próximo do homem assaltado. O intérprete reconhece aquele que agiu com misericórdia. Jesus o chama a agir da mesma maneira.",[[46092,0,2],[46247,3,10],[47443,15,1],[47530,17,10],[48480,28,5],[48993,34,2],[49129,37,6],[50049,45,4],[50524,50,2],[50709,53,10],[51555,64,1],[51660,66,7],[52369,74,6],[52866,81,1],[52952,83,3],[53121,87,6],[53695,94,2],[53911,97,5],[55663,104,5],[56271,110,8],[57020,119,4],[57383,124,8],[58126,133,2],[58333,136,6],[58838,143,7],[59578,151,2],[59760,154,5],[60139,160,9],[62172,171,1],[62271,173,10],[63178,184,9],[64001,194,6],[64497,201,3],[64701,205,4],[65113,210,3],[65340,214,12],[67606,228,5],[68193,234,1],[68281,236,5],[68769,242,1],[68863,244,4],[69262,249,2],[69428,252,5],[69911,258,7]]]]},"a-ovelha-perdida":{"audio":"audio/a-ovelha-perdida.mp3?v=23deec7f32f8","quadros":[[0,"Em Lucas, Jesus acolhe pessoas que certos ouvintes desprezam. Ele pergunta o que faria quem tivesse cem ovelhas e perdesse uma. O pastor deixa as noventa e nove no descampado e vai procurar a que falta. A busca se estende até encontrá-la.",[[108,0,2],[270,3,5],[1204,10,5],[1799,16,6],[2356,23,7],[3053,31,3],[3210,35,6],[3863,42,8],[4541,51,9],[6489,62,3],[6723,66,8],[7464,75,1],[7538,77,3],[7697,81,5],[8217,87,4],[8491,92,7],[9177,100,3],[9526,104,7],[10184,112,1],[10283,114,8],[10907,123,3],[12386,128,1],[12468,130,6],[13055,137,5],[13568,143,2],[13758,146,7],[14356,154,1],[14418,156,4],[14804,161,2],[14997,164,10],[15982,175,1],[16086,177,3],[16357,181,8],[16989,190,1],[17075,192,3],[17249,196,5],[19010,203,1],[19130,205,5],[19706,211,2],[19890,214,7],[20470,222,3],[20806,226,11]]],[22760,"Quando encontra a ovelha, o pastor a põe sobre os ombros com alegria. O animal que andava separado agora volta com quem saiu à sua procura. Em Mateus, a mesma imagem leva os discípulos a prestar atenção aos pequeninos e a não desprezar nenhum deles.",[[22760,0,6],[23174,7,8],[23816,16,1],[23897,18,6],[24782,26,1],[24881,28,6],[25461,35,1],[25572,37,3],[25904,41,5],[26341,47,2],[26532,50,6],[27073,57,3],[27313,61,7],[29118,70,1],[29218,72,6],[29750,79,3],[29960,83,6],[30468,90,8],[31327,99,5],[31847,105,5],[32400,111,3],[32658,115,4],[32927,120,4],[33392,125,1],[33517,127,3],[33832,131,7],[35650,140,2],[35794,143,6],[36842,151,1],[36941,153,5],[37471,159,6],[38097,166,4],[38510,171,2],[38647,174,10],[39541,185,1],[39634,187,7],[40221,195,7],[40884,203,3],[41114,207,10],[41920,218,1],[42025,220,1],[42110,222,3],[42359,226,9],[43190,236,6],[43668,243,5]]],[45404,"Ao chegar em casa, o pastor convida amigos e vizinhos a se alegrarem com ele. A volta de uma ovelha vira motivo de celebração. Em Lucas, Jesus compara essa alegria à do céu por um pecador que se arrepende. Cada retorno importa.",[[45404,0,2],[45570,3,6],[46028,10,2],[46197,13,4],[47068,19,1],[47161,21,6],[47746,28,7],[48297,36,6],[48920,43,1],[49026,45,8],[49724,54,1],[49798,56,2],[50001,59,9],[50638,69,3],[50917,73,3],[52362,78,1],[52472,80,5],[53030,86,2],[53184,89,3],[53411,93,6],[53944,100,4],[54329,105,6],[55001,112,2],[55151,115,10],[57255,127,2],[57415,130,5],[58319,137,5],[58948,143,7],[59557,151,4],[59926,156,7],[60559,164,1],[60652,166,2],[60794,169,3],[61206,173,3],[61427,177,2],[61581,180,7],[62247,188,3],[62427,192,2],[62625,195,9],[64473,206,4],[64866,211,7],[65555,219,7]]]]},"a-moeda-perdida":{"audio":"audio/a-moeda-perdida.mp3?v=3203d6fda486","quadros":[[0,"Uma mulher tem dez moedas de prata e percebe que uma se perdeu dentro de casa. A falta de uma única moeda basta para interromper sua rotina. Jesus começa assim a segunda de três histórias em Lucas sobre perder, procurar e alegrar-se com o reencontro.",[[109,0,3],[315,4,6],[809,11,3],[1081,15,3],[1395,19,6],[1999,26,2],[2158,29,5],[2769,35,1],[2873,37,7],[3639,45,3],[3866,49,3],[4069,53,2],[4268,56,6],[4798,63,6],[5272,70,2],[5449,73,4],[7109,79,1],[7201,81,5],[7778,87,2],[7926,90,3],[8161,94,5],[8600,100,5],[9140,106,5],[9760,112,4],[10066,117,11],[10824,129,3],[11109,133,6],[12886,141,5],[13494,147,6],[14114,154,5],[14563,160,1],[14638,162,7],[15255,170,2],[15423,173,4],[15803,178,9],[16557,188,2],[16713,191,5],[17278,197,5],[17700,203,6],[18628,211,8],[19284,220,1],[19388,222,10],[20262,233,3],[20514,237,1],[20576,239,10]]],[22642,"Ela acende uma lâmpada, varre a casa e procura cuidadosamente. A pequena moeda pode estar num canto em que a luz antes não chegava. A mulher continua o trabalho até encontrá-la. A história acompanha sua atenção paciente do primeiro gesto até a descoberta.",[[22642,0,3],[22914,4,6],[23414,11,3],[23631,15,7],[24612,24,5],[25069,30,1],[25169,32,4],[25748,37,1],[25854,39,7],[26514,47,14],[28953,63,1],[29045,65,7],[29595,73,5],[30135,79,4],[30536,84,5],[30995,90,3],[31251,94,5],[31735,100,2],[31871,103,3],[32032,107,1],[32125,109,3],[32484,113,5],[33022,119,3],[33265,123,7],[35109,132,1],[35194,134,6],[35691,141,8],[36415,150,1],[36503,152,8],[37168,161,3],[37493,165,11],[39441,178,1],[39540,180,8],[40160,189,9],[40877,199,3],[41201,203,7],[41810,211,8],[42570,220,2],[42718,223,8],[43312,232,5],[43896,238,3],[44230,242,1],[44309,244,10]]],[46452,"A mulher chama amigas e vizinhas para se alegrarem com ela. Aquela que procurou sozinha agora compartilha o reencontro. Jesus diz que há uma alegria semelhante diante dos anjos de Deus quando uma pessoa se arrepende. A moeda recuperada ajuda a dar medida a essa alegria.",[[46452,0,1],[46543,2,6],[47029,9,5],[47493,15,6],[48122,22,1],[48221,24,8],[48949,33,4],[49263,38,2],[49463,41,9],[50103,51,3],[50379,55,3],[51857,60,6],[52356,67,3],[52526,71,8],[53149,80,7],[53898,88,5],[54381,94,11],[55305,106,1],[55367,108,10],[57431,120,5],[57988,126,3],[58328,130,3],[58488,134,2],[58582,137,3],[58812,141,7],[59424,149,10],[60276,160,6],[60851,167,3],[61137,171,5],[61581,177,2],[61728,180,4],[62140,185,6],[62537,192,3],[62758,196,6],[63317,203,2],[63522,206,9],[65377,217,1],[65461,219,5],[65986,225,10],[66966,236,5],[67574,242,1],[67667,244,3],[67934,248,6],[68563,255,1],[68661,257,4],[69031,262,7]]]]},"o-filho-prodigo-e-o-irmao-mais-velho":{"audio":"audio/o-filho-prodigo-e-o-irmao-mais-velho.mp3?v=67aa8e466b39","quadros":[[0,"O mais novo de dois filhos pede ao pai a parte da herança que lhe cabe. O pai reparte os bens. Pouco depois, o filho reúne o que recebeu e parte para uma terra distante. Ali, numa vida desregrada, gasta tudo.",[[109,0,1],[179,2,4],[596,7,4],[1054,12,2],[1209,15,4],[1622,20,6],[2100,27,4],[2491,32,2],[2641,35,3],[2979,39,1],[3071,41,5],[3638,47,2],[3799,50,7],[4373,58,3],[4535,62,3],[4709,66,4],[6332,72,1],[6434,74,3],[6787,78,7],[7398,86,2],[7590,89,4],[9223,95,5],[9734,101,6],[10759,109,1],[10845,111,5],[11340,117,5],[11794,123,1],[11867,125,3],[12026,129,7],[12724,137,1],[12830,139,5],[13414,145,4],[13707,150,3],[13954,154,5],[14391,160,8],[16367,170,3],[17071,175,4],[17416,180,4],[17844,185,10],[19160,197,5],[19707,203,4]]],[21283,"Uma fome atinge a região. O filho trabalha cuidando de porcos e passa necessidade. Lembra-se de que na casa do pai até os empregados têm pão e decide voltar. Ele pensa em pedir trabalho, mas o pai corre ao seu encontro, o abraça e prepara uma festa.",[[21283,0,3],[21559,4,4],[22006,9,6],[22625,16,1],[22686,18,6],[24430,26,1],[24511,28,5],[25022,34,8],[25637,43,8],[26291,52,2],[26461,55,6],[27142,62,1],[27247,64,5],[27729,70,11],[29945,83,9],[30696,93,2],[30867,96,3],[31014,100,2],[31186,103,4],[31685,108,2],[31836,111,3],[32176,115,3],[32497,119,2],[32676,122,10],[33592,133,3],[33835,137,3],[34143,141,1],[34247,143,6],[34850,150,6],[36687,158,3],[36928,162,5],[37452,168,2],[37601,171,5],[38080,177,8],[39081,187,3],[39385,191,1],[39472,193,3],[39831,197,5],[40289,203,2],[40426,206,3],[40723,210,8],[41746,220,1],[41852,222,6],[42569,229,1],[42675,231,7],[43303,239,3],[43518,243,5]]],[45286,"O filho mais velho ouve a festa e se recusa a entrar. O pai sai para conversar com ele e escuta sua revolta. Lembra-lhe que tudo o que tem é dele, e chama aquele que voltou de seu irmão. A parábola termina com o convite para celebrar.",[[45286,0,1],[45360,2,5],[45879,8,4],[46270,13,5],[46720,19,4],[47092,24,1],[47178,26,5],[47833,32,1],[47902,34,2],[48100,37,6],[48788,44,1],[48881,46,6],[50668,54,1],[50768,56,3],[51108,60,3],[51442,64,4],[51752,69,9],[52509,79,3],[52787,83,3],[53098,87,1],[53240,89,6],[53907,96,3],[54212,100,7],[56104,109,10],[56718,120,3],[56901,124,4],[57354,129,1],[57428,131,3],[57608,135,3],[57886,139,1],[57979,141,4],[58726,147,1],[58837,149,5],[59307,155,6],[59793,162,3],[59961,166,6],[60475,173,2],[60619,176,3],[60906,180,5],[62486,187,1],[62578,189,8],[63338,198,7],[63927,206,3],[64186,210,1],[64258,212,7],[64958,220,4],[65270,225,8]]]]},"o-servo-que-nao-perdoou":{"audio":"audio/o-servo-que-nao-perdoou.mp3?v=88b386b10ae3","quadros":[[0,"Pedro pergunta a Jesus quantas vezes deve perdoar um irmão. Jesus responde com a história de um rei que acerta contas com os servos. Um homem deve uma quantia impossível de pagar. Depois de ouvir seu pedido de prazo, o rei tem compaixão e cancela a dívida.",[[107,0,5],[561,6,8],[1301,15,1],[1375,17,5],[1974,23,7],[2585,31,5],[3137,37,4],[3559,42,7],[4139,50,2],[4293,53,5],[5893,60,5],[6480,66,8],[7256,75,3],[7506,79,1],[7570,81,8],[8211,90,2],[8359,93,2],[8514,96,3],[8810,100,3],[9019,104,6],[9727,111,6],[10351,118,3],[10593,122,2],[10729,125,6],[12484,133,2],[12675,136,5],[13064,142,4],[13492,147,3],[13710,151,7],[14383,159,10],[15257,170,2],[15412,173,5],[17186,180,6],[17724,187,2],[17873,190,5],[18321,196,3],[18592,200,6],[19193,207,2],[19360,210,5],[20279,217,1],[20365,219,3],[20707,223,3],[20975,227,9],[21828,237,1],[21932,239,7],[22670,247,1],[22774,249,6]]],[24548,"Ao sair, esse servo encontra um colega que lhe deve uma quantia muito menor. Ele o agarra e exige pagamento. O colega pede paciência, quase com as mesmas palavras que o devedor usou diante do rei. O primeiro servo recusa o pedido e manda prendê-lo.",[[24548,0,2],[24714,3,4],[25572,9,4],[25899,14,5],[26496,20,8],[27120,29,2],[27275,32,6],[27912,39,3],[28081,43,3],[28254,47,4],[28675,52,3],[28892,56,7],[29599,64,5],[30074,70,5],[31804,77,3],[32050,81,1],[32138,83,6],[32578,90,1],[32692,92,5],[33239,98,9],[35254,109,1],[35335,111,6],[35955,118,4],[36360,123,9],[37538,134,5],[38064,140,3],[38316,144,2],[38524,147,6],[39141,154,8],[39957,163,3],[40127,167,1],[40204,169,7],[40778,177,4],[41178,182,6],[41764,189,2],[41905,192,3],[43361,197,1],[43445,199,8],[44044,208,5],[44645,214,6],[45343,221,1],[45418,223,6],[46064,230,1],[46168,232,5],[46595,238,9]]],[48337,"Os outros servos, entristecidos, contam ao rei o que aconteceu. O rei chama de volta o homem a quem perdoou e cobra dele a compaixão que recebeu. Jesus encerra a história chamando os discípulos a perdoar de coração. O perdão acolhido deve chegar ao próximo.",[[48337,0,2],[48531,3,6],[49047,10,6],[49998,18,13],[51522,33,6],[52064,40,2],[52211,43,3],[52501,47,1],[52575,49,3],[52780,53,9],[54785,64,1],[54856,66,3],[55166,70,5],[55619,76,2],[55798,79,5],[56362,85,1],[56461,87,5],[56883,93,1],[56976,95,4],[57261,100,7],[57866,108,1],[57973,110,5],[58526,116,4],[58918,121,1],[58994,123,9],[59805,133,3],[59965,137,7],[61839,146,5],[62417,152,7],[63069,160,1],[63137,162,8],[63728,171,8],[64349,180,2],[64486,183,10],[65396,194,1],[65493,196,7],[66089,204,2],[66286,207,7],[68122,216,1],[68206,218,6],[68726,225,8],[69406,234,4],[69828,239,6],[70312,246,2],[70462,249,7]]]]},"os-dois-devedores":{"audio":"audio/os-dois-devedores.mp3?v=7b09b1b0e864","quadros":[[0,"Jesus está à mesa na casa de Simão, um fariseu. Uma mulher molha os pés de Jesus com lágrimas e os unge. Ao perceber o julgamento silencioso do anfitrião, Jesus fala de dois homens que deviam ao mesmo credor. Um devia quinhentos denários e o outro cinquenta.",[[112,0,5],[689,6,4],[1102,11,1],[1183,13,4],[1637,18,2],[1816,21,4],[2270,26,2],[2419,29,5],[3279,36,2],[3434,39,7],[5289,48,3],[5493,52,6],[5983,59,5],[6388,65,2],[6585,68,3],[6873,72,2],[7021,75,5],[7613,81,3],[7843,85,8],[8652,94,1],[8760,96,2],[8942,99,4],[10370,105,2],[10535,108,8],[11225,117,1],[11299,119,10],[12161,130,10],[13223,141,2],[13366,144,9],[14444,155,5],[15064,161,4],[15490,166,2],[15644,169,4],[16047,174,6],[16553,181,3],[16713,185,6],[17231,192,2],[17372,195,5],[17876,201,6],[19708,209,2],[19884,212,5],[20338,218,10],[21041,229,8],[21707,238,1],[21814,240,1],[21915,242,5],[22375,248,9]]],[24303,"Nenhum dos dois tinha como pagar, e o credor cancelou as duas dívidas. Jesus pergunta a Simão qual deles amará mais aquele que os perdoou. Simão responde que será aquele a quem mais foi perdoado. Jesus aprova a resposta e volta os olhos para a mulher.",[[24303,0,6],[24797,7,3],[25038,11,4],[25434,16,5],[25813,22,4],[26172,27,5],[27052,34,1],[27152,36,1],[27245,38,6],[27759,45,8],[28402,54,2],[28601,57,4],[28981,62,7],[30907,71,5],[31514,77,8],[32265,86,1],[32344,88,5],[32864,94,4],[33239,99,5],[33724,105,5],[34120,111,4],[34502,116,6],[35004,123,3],[35142,127,2],[35311,130,7],[37016,139,5],[37527,145,8],[38322,154,3],[38475,158,4],[38888,163,6],[39377,170,1],[39469,172,4],[39766,177,4],[40192,182,3],[40453,186,8],[42386,196,5],[42964,202,6],[43604,209,1],[43666,211,8],[44573,220,1],[44677,222,5],[45206,228,2],[45403,231,5],[45822,237,4],[46115,242,1],[46177,244,6]]],[47920,"Jesus lembra os gestos de cuidado que a mulher lhe ofereceu à mesa. O amor demonstrado por ela torna visível a dimensão do perdão. Diante dos convidados, Jesus declara que seus pecados estão perdoados e a despede em paz, afirmando que sua fé a salvou.",[[47920,0,5],[48527,6,6],[48982,13,2],[49137,16,6],[49747,23,2],[49904,26,7],[50569,34,3],[50757,38,1],[50819,40,6],[51337,47,3],[51497,51,8],[52243,60,1],[52336,62,4],[53960,68,1],[54060,70,4],[54430,75,11],[55429,87,3],[55664,91,3],[55933,95,5],[56434,101,7],[57126,109,1],[57200,111,8],[57886,120,2],[58023,123,6],[59730,131,6],[60291,138,3],[60551,142,10],[61831,154,5],[62425,160,7],[63051,168,3],[63211,172,4],[63632,177,7],[64387,185,5],[64821,191,9],[65541,201,1],[65655,203,1],[65730,205,7],[66460,213,2],[66650,216,3],[67428,221,9],[68210,231,3],[68370,235,3],[68687,239,2],[68986,242,1],[69070,244,6]]]]},"o-amigo-a-meia-noite":{"audio":"audio/o-amigo-a-meia-noite.mp3?v=285f3b2b5266","quadros":[[0,"Depois de ensinar os discípulos a orar, Jesus propõe uma situação. Um viajante chega à meia-noite à casa de um amigo. O anfitrião não tem pão para oferecer. Para receber o hóspede, sai no escuro e pede três pães a outro amigo.",[[103,0,6],[648,7,2],[828,10,7],[1386,18,2],[1521,21,10],[2451,32,1],[2543,34,4],[3289,40,5],[3921,46,6],[4449,53,3],[4659,57,8],[6600,67,2],[6762,70,8],[7489,79,5],[7948,85,1],[8029,87,10],[8897,98,1],[8977,100,4],[9477,105,2],[9618,108,2],[9778,111,5],[11455,118,1],[11554,120,9],[12284,130,3],[12569,134,3],[12830,138,3],[13154,142,4],[13437,147,8],[15521,157,4],[15918,162,7],[16563,170,1],[16681,172,7],[17633,181,3],[17965,185,2],[18125,188,6],[18732,195,1],[18836,197,4],[19246,202,4],[19655,207,4],[20073,212,1],[20172,214,5],[20632,220,5]]],[22298,"Do outro lado da porta, o amigo responde que a casa já está fechada e os filhos estão deitados com ele. Levantar àquela hora exige esforço. Mesmo assim, Jesus diz que a insistência de quem está do lado de fora acaba fazendo o homem se levantar.",[[22298,0,2],[22481,3,5],[22916,9,4],[23331,14,2],[23505,17,5],[24411,24,1],[24524,26,5],[25007,32,8],[25797,41,3],[25958,45,1],[26063,47,4],[26575,52,2],[26780,55,4],[27141,60,7],[27932,68,1],[28038,70,2],[28276,73,6],[28739,80,5],[29182,86,8],[29861,95,3],[30120,99,3],[31572,104,8],[32212,113,6],[32709,120,4],[33032,125,5],[33572,131,7],[35577,140,5],[36061,146,5],[36888,153,5],[37462,159,3],[37801,163,3],[37942,167,1],[38009,169,11],[38984,181,2],[39141,184,4],[39427,189,4],[39809,194,2],[39956,197,4],[40401,202,2],[40563,205,4],[41011,210,5],[41538,216,7],[42207,224,1],[42307,226,5],[42725,232,2],[42918,235,8]]],[44904,"O amigo dá ao anfitrião tudo de que ele precisa para receber seu hóspede. Jesus liga a cena ao convite para pedir, procurar e bater. Conclui falando de um Pai que conhece as necessidades dos filhos e dá o Espírito Santo a quem lhe pede.",[[44904,0,1],[45003,2,5],[45494,8,2],[45724,11,2],[45891,14,9],[46643,24,4],[47073,29,2],[47239,32,3],[47467,36,3],[47721,40,7],[48432,48,4],[48730,53,7],[49387,61,3],[49675,65,7],[51439,74,5],[52046,80,4],[52441,85,1],[52521,87,4],[53002,92,2],[53151,95,7],[53846,103,4],[54150,108,5],[54966,115,8],[55674,124,1],[55779,126,5],[57551,133,7],[58188,141,7],[58804,149,2],[58951,152,2],[59115,155,3],[59461,159,3],[59641,163,7],[60281,171,2],[60466,174,12],[61570,187,3],[61872,191,6],[62340,198,1],[62448,200,2],[62665,203,1],[62745,205,8],[63513,214,5],[64080,220,1],[64173,222,4],[64466,227,3],[64622,231,4]]]]},"a-viuva-persistente-e-o-juiz":{"audio":"audio/a-viuva-persistente-e-o-juiz.mp3?v=e9bb2b5eb113","quadros":[[0,"Jesus quer ensinar os discípulos a orar sempre, sem desanimar. Conta que numa cidade vivia um juiz que não temia a Deus e não respeitava as pessoas. Uma viúva se apresenta diante dele e pede que sua causa contra um adversário seja julgada com justiça.",[[112,0,5],[719,6,4],[1026,11,7],[1586,19,2],[1721,22,10],[2649,33,1],[2750,35,4],[3074,40,6],[4029,48,3],[4370,52,9],[6480,63,5],[6934,69,3],[7106,73,4],[7410,78,6],[8049,85,5],[8506,91,2],[8662,94,4],[9103,99,3],[9256,103,3],[9500,107,5],[9915,113,1],[10009,115,4],[10412,120,1],[10499,122,3],[10720,126,10],[11609,137,2],[11791,140,7],[13795,149,3],[14018,153,5],[14529,159,2],[14730,162,9],[15477,172,6],[16075,179,4],[16530,184,1],[16635,186,4],[17109,191,3],[17264,195,3],[17575,199,5],[18101,205,6],[18633,212,2],[18788,215,10],[19656,226,4],[20185,231,7],[20845,239,3],[21083,243,7]]],[23050,"O juiz se recusa a atendê-la durante algum tempo. A viúva, porém, continua voltando. O homem sabe que sua decisão não vem da reverência a Deus nem do respeito às pessoas. Ele muda de ideia porque quer pôr fim às idas da mulher ao tribunal.",[[23050,0,1],[23135,2,4],[23566,7,2],[23736,10,6],[24474,17,1],[24554,19,9],[25142,29,7],[25694,37,5],[26112,43,5],[27763,50,1],[27847,52,5],[28754,59,5],[29587,66,8],[30287,75,8],[32201,85,1],[32321,87,5],[32694,93,4],[33179,98,3],[33335,102,3],[33632,106,7],[34313,114,3],[34578,118,3],[34850,122,2],[34998,125,10],[35881,136,1],[35976,138,4],[36405,143,3],[36700,147,2],[36834,150,8],[37640,159,2],[37845,162,7],[39841,171,3],[40082,175,4],[40536,180,2],[40716,183,5],[41180,189,6],[41589,196,4],[41915,201,3],[42227,205,3],[42602,209,2],[42843,212,4],[43191,217,2],[43335,220,6],[43795,227,2],[43955,230,8]]],[45777,"O juiz resolve atender à viúva. Jesus pede que os discípulos ouçam até onde a insistência chegou diante de um juiz injusto. Depois pergunta se Deus deixará de fazer justiça aos que clamam a ele. A história termina com uma pergunta sobre a fé que resiste à espera.",[[45777,0,1],[45862,2,4],[46283,7,7],[46972,15,7],[47500,23,1],[47592,25,5],[49309,32,5],[49917,38,4],[50369,43,3],[50507,47,2],[50644,50,10],[51567,61,5],[52017,67,3],[52326,71,4],[52672,76,1],[52741,78,11],[53702,90,6],[54188,97,6],[54746,104,2],[54895,107,2],[55050,110,4],[55445,115,7],[57322,124,6],[57925,131,8],[58646,140,2],[58863,143,4],[59245,148,7],[59858,156,2],[60028,159,5],[60489,165,7],[61261,173,3],[61491,177,3],[61655,181,6],[62093,188,1],[62193,190,3],[63653,195,1],[63752,197,8],[64374,206,7],[64969,214,3],[65222,218,3],[65432,222,8],[66169,231,5],[66630,237,1],[66729,239,2],[67022,242,3],[67191,246,7],[67897,254,1],[67978,256,6]]]]},"o-fariseu-e-o-publicano":{"audio":"audio/o-fariseu-e-o-publicano.mp3?v=37fdba976013","quadros":[[0,"Jesus conta esta parábola aos que confiavam na própria justiça e desprezavam os outros. Dois homens sobem ao templo para orar. Um é fariseu. O outro é publicano, um cobrador de impostos. Os dois chegam ao mesmo lugar e fazem orações muito diferentes.",[[112,0,5],[719,6,5],[1154,12,4],[1573,17,8],[2332,26,3],[2555,30,3],[2722,34,9],[3427,44,2],[3609,47,7],[4247,55,7],[5091,63,1],[5188,65,11],[6105,77,2],[6298,80,6],[8112,88,4],[8504,93,6],[8984,100,5],[9377,106,2],[9534,109,6],[10058,116,4],[10359,121,4],[12013,127,2],[12207,130,1],[12293,132,7],[14137,141,1],[14265,143,5],[14805,149,1],[14940,151,9],[16005,162,2],[16199,165,8],[16891,174,2],[17072,177,8],[19109,187,2],[19313,190,4],[19708,195,6],[20168,202,2],[20316,205,5],[20820,211,5],[21246,217,1],[21351,219,5],[21928,225,7],[22634,233,5],[23106,239,10]]],[25237,"O fariseu agradece por ser diferente dos demais e enumera seu jejum e seu dízimo. O publicano fica à distância. Nem levanta os olhos para o céu. Batendo no peito, pede a Deus misericórdia e reconhece que é pecador.",[[25237,0,1],[25318,2,7],[25969,10,8],[26728,19,3],[26967,23,3],[27268,27,9],[28078,37,3],[28296,41,6],[28863,48,1],[28968,50,7],[29577,58,3],[29861,62,5],[30372,68,1],[30447,70,3],[30759,74,6],[32528,82,1],[32613,84,9],[33326,94,4],[33821,99,1],[33901,101,9],[35881,112,3],[36142,116,7],[36757,124,2],[36954,127,5],[37373,133,4],[37664,138,1],[37738,140,3],[39272,145,7],[39868,153,2],[40025,156,5],[40936,163,4],[41377,168,1],[41470,170,4],[41833,175,12],[42932,188,1],[43038,190,9],[43882,200,3],[44081,204,1],[44225,206,7]]],[46169,"Jesus diz que o publicano volta para casa justificado diante de Deus. A oração de quem comparou sua conduta à dos outros expôs o desprezo que carregava. O homem que reconheceu a própria necessidade recebeu misericórdia. Jesus encerra dizendo que quem se humilha será exaltado.",[[46169,0,5],[46737,6,3],[47067,10,3],[47217,14,1],[47286,16,9],[48011,26,5],[48541,32,4],[48873,37,4],[49337,42,11],[50426,54,6],[50966,61,2],[51122,64,4],[52783,70,1],[52883,72,6],[53484,79,2],[53633,82,4],[53932,87,8],[54552,96,3],[54848,100,7],[55517,108,1],[55612,110,3],[55872,114,6],[56401,121,5],[56953,127,1],[57027,129,8],[57871,138,3],[58050,142,9],[59885,153,1],[60013,155,5],[60442,161,3],[60610,165,10],[61446,176,1],[61533,178,7],[62171,186,11],[63149,198,7],[63773,206,12],[66062,220,5],[66639,226,7],[67300,234,7],[67930,242,3],[68104,246,4],[68388,251,2],[68598,254,7],[69010,262,4],[69389,267,8]]]]},"a-figueira-sem-frutos":{"audio":"audio/a-figueira-sem-frutos.mp3?v=6e6f92c18256","quadros":[[0,"Depois de chamar os ouvintes ao arrependimento, Jesus descreve um homem que tem uma figueira plantada na vinha. Há três anos ele procura frutos nela sem encontrar nenhum. Diante dos galhos vazios, pergunta ao responsável pela vinha por que a árvore ainda ocupa o terreno.",[[106,0,6],[644,7,2],[794,10,6],[1289,17,2],[1437,20,8],[2200,29,2],[2364,32,14],[3838,48,5],[4409,54,8],[5178,63,2],[5339,66,5],[5718,72,3],[5899,76,3],[6148,80,3],[6358,84,8],[6991,93,8],[7673,102,2],[7864,105,5],[9431,112,2],[9541,115,4],[9942,120,4],[10330,125,3],[10631,129,7],[11274,137,6],[11990,144,4],[12409,149,3],[12762,153,9],[13480,163,6],[15163,171,6],[15722,178,3],[15985,182,6],[16497,189,6],[17423,197,8],[18177,206,2],[18326,209,11],[19413,221,4],[19778,226,5],[20185,232,3],[20428,236,3],[20616,240,1],[20734,242,6],[21277,249,5],[21736,255,5],[22308,261,1],[22383,263,7]]],[24131,"O dono quer cortar a figueira. O agricultor pede mais um ano. Nesse tempo, vai cavar a terra ao redor e pôr adubo. A árvore recebe mais uma estação de cuidado, com a oportunidade de produzir aquilo que o dono veio procurar.",[[24131,0,1],[24233,2,4],[24627,7,4],[24933,12,6],[25483,19,1],[25557,21,8],[27381,31,1],[27480,33,10],[28310,44,4],[28735,49,4],[29160,54,2],[29360,57,3],[30855,62,5],[31289,68,5],[32156,75,3],[32464,79,5],[32908,85,1],[33019,87,5],[33503,93,2],[33646,96,5],[34161,102,1],[34265,104,3],[34569,108,5],[36219,115,1],[36347,117,6],[36886,124,6],[37537,131,4],[37977,136,3],[38257,140,7],[38935,148,2],[39097,151,7],[40105,160,3],[40374,164,1],[40463,166,12],[41590,179,2],[41750,182,8],[42404,191,6],[42936,198,3],[43121,202,1],[43207,204,4],[43602,209,4],[43989,214,8]]],[45928,"O agricultor admite que, se a figueira continuar sem fruto, poderá ser cortada. Jesus encerra o relato deixando em aberto o destino da árvore. A espera inclui tanto a paciência de quem cuida quanto a urgência de responder enquanto há tempo.",[[45928,0,1],[46028,2,10],[46848,13,6],[47453,20,3],[48056,25,2],[48273,28,1],[48335,30,8],[48975,39,9],[49718,49,3],[50047,53,5],[50967,60,6],[51517,67,3],[51807,71,7],[53707,80,5],[54285,86,7],[54938,94,1],[55001,96,6],[55646,103,8],[56323,112,2],[56500,115,6],[57128,122,1],[57202,124,7],[57860,132,2],[58034,135,6],[59734,143,1],[59833,145,6],[60402,152,6],[60963,159,5],[61465,165,1],[61540,167,9],[62370,177,2],[62519,180,4],[62833,185,5],[63343,191,6],[63828,198,1],[63897,200,8],[64558,209,2],[64707,212,9],[65475,222,8],[66100,231,2],[66187,234,5]]]]},"os-dois-construtores":{"audio":"audio/os-dois-construtores.mp3?v=120beca22df3","quadros":[[0,"Jesus encerra um ensinamento comparando duas pessoas que constroem casas. Uma faz questão de firmar a construção sobre rocha. Em Lucas, ela cava fundo para assentar os alicerces. A outra ergue sua casa sobre a areia ou diretamente no chão, sem fundamento.",[[112,0,5],[689,6,7],[1319,14,2],[1481,17,11],[2429,29,10],[3279,40,4],[3682,45,7],[4369,53,3],[4534,57,9],[5350,67,5],[7186,74,3],[7461,78,3],[7824,82,7],[8376,90,2],[8526,93,6],[9045,100,1],[9131,102,10],[10029,113,5],[10482,119,5],[12116,126,2],[12278,129,5],[13216,136,3],[13513,140,4],[13954,145,5],[14507,151,4],[14794,156,8],[15421,165,2],[15586,168,9],[17677,179,1],[17806,181,5],[18266,187,5],[18578,193,3],[18901,197,4],[19407,202,5],[19870,208,1],[19951,210,5],[20460,216,2],[20634,219,11],[21623,231,2],[21766,234,4],[22483,240,3],[22818,244,10]]],[24915,"Chegam a chuva e as águas, e o vento bate contra as casas. Em Lucas, a corrente do rio avança contra a construção. O tempo ruim alcança os dois moradores. Nessa hora, o que estava escondido sob cada casa faz diferença.",[[24915,0,6],[25430,7,1],[25535,9,5],[26175,15,1],[26287,17,2],[26491,20,5],[27411,27,1],[27511,29,1],[27597,31,5],[28086,37,4],[28521,42,6],[29029,49,2],[29240,52,5],[31070,59,2],[31231,62,5],[32167,69,1],[32271,71,8],[32990,80,2],[33125,83,3],[33451,87,6],[33950,94,6],[34483,101,1],[34556,103,10],[36633,115,1],[36751,117,5],[37224,123,4],[37611,128,7],[38130,136,2],[38317,139,4],[38696,144,9],[40736,155,5],[41180,161,4],[41870,167,1],[41970,169,3],[42125,173,6],[42670,180,9],[43476,190,3],[43784,194,4],[44257,199,4],[44735,204,3],[45042,208,9]]],[47003,"A casa sobre a rocha fica de pé. A outra cai. Jesus diz que quem ouve suas palavras e as pratica é como quem construiu sobre a rocha. A parábola põe o fundamento da vida naquilo que o ouvinte faz com o ensinamento que recebeu.",[[47003,0,1],[47105,2,4],[47620,7,5],[48079,13,1],[48164,15,5],[48705,21,4],[49186,26,2],[49368,29,2],[50759,33,1],[50888,35,5],[51447,41,3],[52949,46,5],[53507,52,3],[53848,56,3],[54016,60,4],[54321,65,4],[54675,70,4],[55064,75,8],[55926,84,1],[56034,86,2],[56215,89,7],[56964,97,1],[57106,99,4],[57486,104,4],[57766,109,9],[58545,119,5],[58977,125,1],[59063,127,5],[60700,134,1],[60792,136,8],[61548,145,3],[61862,149,1],[61924,151,10],[62795,162,2],[62981,165,4],[63395,170,7],[63972,178,3],[64133,182,1],[64214,184,7],[64876,192,3],[65235,196,3],[65476,200,1],[65581,202,11],[66503,214,3],[66665,218,7]]]]},"os-dois-filhos":{"audio":"audio/os-dois-filhos.mp3?v=e6a2f6034595","quadros":[[0,"Jesus se dirige aos chefes dos sacerdotes e aos anciãos. Conta que um pai pede aos dois filhos que trabalhem na vinha. Um recusa o pedido. O outro responde com deferência e promete ir. O que cada um faz depois muda o peso de suas palavras.",[[112,0,5],[709,6,2],[883,9,6],[1443,16,3],[1667,20,6],[2292,27,3],[2502,31,10],[3583,42,1],[3689,44,3],[3950,48,7],[5829,57,5],[6284,63,3],[6434,67,2],[6603,70,3],[6949,74,4],[7348,79,3],[7603,83,4],[7997,88,6],[8488,95,3],[8647,99,9],[9307,109,2],[9504,112,5],[11074,119,2],[11259,122,6],[11953,129,1],[12028,131,6],[13841,139,1],[13970,141,5],[14405,147,8],[15185,156,3],[15428,160,10],[16413,171,1],[16518,173,7],[17236,181,3],[18717,185,1],[18798,187,3],[18988,191,4],[19455,196,2],[19629,199,3],[20028,203,6],[20641,210,4],[21111,215,1],[21185,217,4],[21708,222,2],[21862,225,4],[22251,230,8]]],[24262,"O filho que havia recusado reconsidera e vai trabalhar na vinha. Aquele que havia concordado fica para trás. Jesus pergunta aos ouvintes qual dos dois fez a vontade do pai. A resposta depende de quem de fato foi trabalhar, e todos reconhecem isso.",[[24262,0,1],[24336,2,5],[24846,8,3],[25051,12,5],[25427,18,8],[26254,27,11],[27216,39,1],[27315,41,3],[27592,45,9],[28265,55,2],[28488,58,5],[30046,65,6],[30545,72,3],[30752,76,5],[31135,82,10],[32019,93,4],[32513,98,4],[32851,103,4],[34551,109,5],[35158,115,8],[35898,124,3],[36120,128,8],[36907,137,4],[37242,142,3],[37489,146,4],[37907,151,3],[38190,155,1],[38268,157,7],[38915,165,2],[39095,168,3],[40588,173,1],[40659,175,8],[41531,184,7],[42142,192,2],[42290,195,4],[42578,200,2],[42738,203,4],[43244,208,3],[43528,212,9],[44608,223,1],[44728,225,5],[45268,231,10],[46170,242,4]]],[47704,"Jesus aplica a história à resposta que deram a João Batista. Cobradores de impostos e prostitutas acreditaram em João. As autoridades viram isso acontecer e ainda assim não mudaram de atitude. Como o filho que foi à vinha, importa o que alguém faz depois de ouvir.",[[47704,0,5],[48282,6,6],[48936,13,1],[49011,15,8],[49660,24,1],[49741,26,8],[50615,35,3],[50811,39,5],[51235,45,1],[51309,47,4],[51681,52,7],[53617,61,10],[54395,72,2],[54568,75,8],[55398,84,1],[55505,86,11],[56377,98,11],[57271,110,2],[57401,113,4],[58992,119,2],[59180,122,11],[60223,134,5],[60660,140,4],[61043,145,9],[61811,155,1],[61923,157,5],[62366,163,5],[62818,169,3],[63071,173,7],[63640,181,2],[63812,184,7],[65704,193,4],[66066,198,1],[66153,200,5],[66654,206,3],[66827,210,3],[67136,214,1],[67237,216,5],[67991,223,7],[68683,231,1],[68758,233,3],[68920,237,6],[69360,244,3],[69743,248,6],[70300,255,2],[70449,258,5]]]]},"os-trabalhadores-da-vinha":{"audio":"audio/os-trabalhadores-da-vinha.mp3?v=46d04c06ed1f","quadros":[[0,"Um dono de vinha sai bem cedo para contratar trabalhadores. Combina com eles o pagamento de um denário pelo dia e os envia à vinha. O primeiro grupo começa enquanto ainda há um dia inteiro de trabalho pela frente.",[[108,0,2],[258,3,4],[623,8,2],[802,11,5],[1195,17,3],[1530,21,3],[1820,25,4],[2310,30,4],[2633,35,9],[3409,45,13],[5715,60,7],[6353,68,3],[6634,72,4],[7022,77,1],[7110,79,9],[7924,89,2],[8066,92,2],[8215,95,7],[8727,103,4],[9066,108,3],[9433,112,1],[9540,114,2],[9722,117,5],[10173,123,1],[10254,125,5],[11820,132,1],[11901,134,8],[12511,143,5],[13041,149,6],[13669,156,8],[14283,165,5],[14730,171,2],[14821,174,2],[14981,177,3],[15327,181,7],[15894,189,2],[16071,192,8],[16729,201,4],[17066,206,6]]],[18841,"Ao longo do dia, o proprietário volta à praça e chama mais trabalhadores. Perto do fim, encontra gente ainda esperando por serviço, pois ninguém a contratara. Também manda esse grupo à vinha. Ao anoitecer, pede ao administrador que pague os últimos primeiro.",[[18841,0,2],[19036,3,5],[19444,9,2],[19604,12,3],[20336,17,1],[20427,19,12],[21457,32,5],[21995,38,1],[22076,40,5],[22725,46,1],[22831,48,5],[23292,54,4],[23723,59,13],[25984,74,5],[26478,80,2],[26622,83,3],[27336,88,8],[28015,97,5],[28463,103,5],[28906,109,9],[29645,119,3],[29868,123,7],[31004,132,4],[31465,137,7],[31991,145,1],[32065,147,10],[34005,159,6],[34498,166,5],[34966,172,4],[35293,177,5],[35823,183,1],[35906,185,5],[37488,192,2],[37660,195,9],[38896,206,4],[39326,211,2],[39493,214,13],[40553,228,3],[40746,232,5],[41205,238,2],[41407,241,7],[42051,249,8]]],[43831,"Todos recebem um denário. Os primeiros reclamam porque trabalharam mais tempo. O dono lembra que cumpriu o acordo e que decidiu ser generoso com os outros. Ao falar do Reino, Jesus coloca quem chegou cedo diante da alegria ou do ressentimento pela bondade recebida por outro.",[[43831,0,5],[44347,6,7],[45059,14,2],[45243,17,7],[46970,26,2],[47150,29,9],[47827,39,8],[48513,48,6],[48909,55,11],[49725,67,4],[50155,72,5],[51779,79,1],[51879,81,4],[52264,86,6],[52729,93,3],[52913,97,7],[53449,105,1],[53536,107,6],[54201,114,1],[54308,116,3],[54488,120,7],[55140,128,3],[55419,132,8],[56228,141,3],[56478,145,2],[56678,148,6],[58487,156,2],[58653,159,5],[59132,165,2],[59274,168,5],[60133,175,5],[60755,181,6],[61417,188,4],[61683,193,6],[62158,200,4],[62641,205,6],[63211,212,2],[63385,215,7],[64017,223,2],[64190,226,2],[64319,229,13],[65420,243,4],[65760,248,7],[66406,256,8],[67196,265,3],[67427,269,5]]]]},"os-lavradores-que-matam-o-herdeiro":{"audio":"audio/os-lavradores-que-matam-o-herdeiro.mp3?v=299c320a7779","quadros":[[0,"Um proprietário prepara uma vinha, cerca o terreno, cava um lugar para espremer as uvas e constrói uma torre. Em seguida, arrenda a vinha a lavradores e viaja. Quando chega o tempo dos frutos, manda servos receberem a parte que lhe cabe.",[[105,0,2],[263,3,12],[1254,16,7],[1839,24,3],[2088,28,5],[2847,35,5],[3358,41,1],[3433,43,7],[4404,52,4],[4868,57,2],[5030,60,5],[5488,66,4],[5766,71,8],[6423,80,2],[6638,83,4],[7148,88,1],[7254,90,8],[7930,99,3],[8173,103,5],[9800,110,2],[9955,113,7],[10913,122,7],[11371,130,1],[11481,132,5],[11907,138,1],[11969,140,10],[12765,151,1],[12871,153,5],[14614,160,6],[15031,167,5],[15491,173,1],[15577,175,5],[16044,181,3],[16316,185,6],[17360,193,5],[17813,199,6],[18399,206,9],[19146,216,1],[19240,218,5],[19822,224,3],[19983,228,3],[20156,232,4]]],[21775,"Os lavradores agridem os mensageiros e matam alguns deles. O dono envia outros, mas a violência se repete. A vinha continua sob os cuidados de gente que tomou a decisão de reter seus frutos. Por fim, o proprietário envia o próprio filho, esperando que o respeitem.",[[21775,0,2],[21959,3,10],[22719,14,7],[23237,22,2],[23399,25,11],[24453,37,1],[24558,39,5],[25037,45,6],[25556,52,5],[27315,59,1],[27417,61,4],[27823,66,5],[28247,72,6],[29263,80,3],[29567,84,1],[29648,86,9],[30406,96,2],[30598,99,6],[32489,107,1],[32599,109,5],[33006,115,8],[33697,124,3],[34009,128,2],[34199,131,8],[34951,140,2],[35117,143,5],[35606,149,3],[35780,153,5],[36229,159,1],[36302,161,7],[36976,169,2],[37120,172,5],[37582,178,4],[37978,183,6],[39869,191,3],[40155,195,3],[40886,200,1],[40979,202,12],[42015,215,5],[42449,221,1],[42531,223,7],[43149,231,5],[43976,238,9],[44721,248,3],[44885,252,1],[44947,254,9]]],[46908,"Os lavradores reconhecem o herdeiro e o matam, pensando em ficar com a herança. Jesus pergunta o que fará o dono quando voltar. Os chefes religiosos percebem que a parábola fala deles. A vinha será confiada a outros, e a pedra rejeitada se tornará a principal.",[[46908,0,2],[47090,3,10],[47842,14,10],[48777,25,1],[48855,27,8],[49552,36,1],[49696,38,1],[49772,40,5],[50662,47,8],[51347,56,2],[51477,59,5],[52021,65,3],[52281,69,1],[52362,71,7],[54067,80,5],[54675,86,8],[55407,95,1],[55484,97,3],[55650,101,4],[56046,106,1],[56133,108,4],[56534,113,6],[56928,120,6],[58755,128,2],[58916,131,6],[59492,138,10],[60527,149,8],[61328,158,3],[61490,162,1],[61565,164,8],[62286,173,4],[62834,178,5],[64585,185,1],[64695,187,5],[65104,193,4],[65483,198,8],[66277,207,1],[66376,209,6],[67337,217,1],[67436,219,1],[67542,221,5],[68075,227,9],[68991,237,2],[69197,240,7],[69825,248,1],[69899,250,9]]]]},"o-grande-banquete":{"audio":"audio/o-grande-banquete.mp3?v=0144e1622df9","quadros":[[0,"À mesa, um dos presentes fala da felicidade de participar do banquete no Reino de Deus. Jesus responde com a história de um homem que prepara uma grande ceia. Quando tudo está pronto, o anfitrião manda seu servo chamar as pessoas já convidadas.",[[107,0,1],[209,2,4],[1039,8,2],[1237,11,3],[1459,15,9],[2364,25,4],[2789,30,2],[2949,33,10],[3919,44,2],[4084,47,10],[4978,58,2],[5108,61,8],[5828,70,2],[5978,73,5],[6453,79,2],[6608,82,4],[8275,88,5],[8863,94,8],[9639,103,3],[9889,107,1],[9953,109,8],[10594,118,2],[10742,121,2],[10899,124,5],[11282,130,3],[11452,134,7],[12073,142,3],[12302,146,6],[12780,153,4],[14406,159,6],[14840,166,4],[15272,171,4],[15628,176,6],[16515,184,1],[16620,186,9],[17364,196,5],[17842,202,3],[18114,206,5],[18694,212,6],[19177,219,2],[19365,222,7],[20018,230,2],[20207,233,10]]],[22273,"Os convidados começam a se desculpar. Um comprou um campo, outro quer examinar cinco juntas de bois, e um terceiro acabou de se casar. Ao saber das recusas, o anfitrião manda o servo procurar nas ruas quem vive na pobreza e quem enfrenta limitações físicas.",[[22273,0,2],[22460,3,10],[23392,14,7],[24091,22,1],[24165,24,2],[24363,27,9],[26513,38,2],[26663,41,7],[27165,49,2],[27333,52,5],[28197,59,5],[28669,65,4],[28957,70,8],[29736,79,5],[30301,85,6],[30839,92,2],[31000,95,4],[31829,101,1],[31936,103,2],[32100,106,8],[32852,115,6],[33393,122,2],[33542,125,2],[33760,128,5],[35573,135,2],[35739,138,5],[36230,144,3],[36490,148,7],[37642,157,1],[37748,159,9],[38492,169,5],[38951,175,1],[39021,177,5],[39635,183,8],[40303,192,3],[40611,196,4],[41083,201,4],[41350,206,4],[41731,211,2],[41903,214,7],[42699,222,1],[42806,224,4],[43096,229,8],[43789,238,10],[44731,249,7]]],[46637,"Ainda sobra lugar. O anfitrião manda estender o convite pelos caminhos até que a casa se encha. Quem havia recusado fica fora da ceia. À mesa de Jesus, a história amplia a pergunta sobre quem participa do banquete e mostra que o convite pede uma resposta.",[[46637,0,5],[47102,6,5],[47634,12,5],[49400,19,1],[49500,21,9],[50241,31,5],[50678,37,8],[51290,46,1],[51376,48,7],[52069,56,5],[52501,62,8],[53169,71,3],[53509,75,3],[53669,79,1],[53774,81,4],[54221,86,2],[54469,89,5],[56006,96,4],[56296,101,5],[56658,107,8],[57509,116,4],[57990,121,4],[58478,126,2],[58645,129,4],[60267,135,1],[60367,137,4],[60757,142,2],[60919,145,5],[61905,152,1],[62017,154,8],[62642,163,6],[63146,170,1],[63239,172,8],[63981,181,5],[64443,187,4],[64716,192,9],[65576,202,2],[65705,205,8],[66516,214,1],[66615,216,6],[67245,223,3],[67406,227,1],[67480,229,7],[68175,237,4],[68590,242,3],[68788,246,8]]]]},"as-bodas-do-filho-do-rei":{"audio":"audio/as-bodas-do-filho-do-rei.mp3?v=4ccf69122f86","quadros":[[0,"Em Mateus, Jesus compara o Reino dos céus a um rei que prepara o casamento do filho. Os primeiros convidados se recusam a ir. Um prefere cuidar do campo, outro vai aos negócios, e outros agridem e matam os servos. O rei manda castigar os responsáveis.",[[108,0,2],[251,3,6],[1293,11,5],[1909,17,7],[2522,25,1],[2609,27,5],[3102,33,3],[3323,37,4],[3673,42,1],[3748,44,2],[3911,47,3],[4199,51,3],[4366,55,7],[4982,63,1],[5058,65,9],[5884,75,2],[6020,78,5],[7682,85,2],[7862,88,9],[8565,98,10],[9522,109,2],[9688,112,7],[10409,120,1],[10535,122,3],[12001,126,2],[12156,129,7],[12798,137,6],[13295,144,2],[13456,147,5],[14339,154,5],[14802,160,3],[15075,164,3],[15323,168,8],[16500,178,1],[16645,180,6],[17184,187,7],[17785,195,1],[17884,197,5],[18381,203,2],[18517,206,6],[20276,214,1],[20350,216,3],[20680,220,5],[21139,226,8],[21859,235,2],[22030,238,12]]],[24504,"O banquete está preparado. O rei envia seus servos às saídas dos caminhos e manda convidar quem encontrarem. Eles reúnem pessoas más e boas. O salão, antes vazio, fica cheio de convidados que receberam o chamado longe da mesa.",[[24504,0,1],[24589,2,8],[25288,11,4],[25649,16,9],[27671,27,1],[27742,29,3],[28064,33,5],[28472,39,4],[28861,44,6],[29451,51,2],[29661,54,6],[30260,61,3],[30509,65,8],[31206,74,1],[31311,76,5],[31765,82,8],[32437,91,4],[32722,96,11],[34687,109,4],[35001,114,6],[35528,121,7],[36191,129,3],[36541,133,1],[36648,135,4],[38410,141,1],[38481,143,5],[39331,150,5],[39771,156,5],[40699,163,4],[41190,168,5],[41710,174,2],[41877,177,10],[42840,188,3],[42987,192,9],[43809,202,1],[43883,204,7],[44549,212,5],[45009,218,2],[45178,221,4]]],[46799,"Ao entrar, o rei vê um homem que não veste a roupa da festa. Pergunta como ele entrou assim, e o homem fica sem resposta. O rei manda retirá-lo. A história reúne a amplitude do convite com a seriedade da resposta de quem chega ao banquete.",[[46799,0,2],[46972,3,6],[47871,11,1],[47971,13,3],[48304,17,2],[48475,20,2],[48638,23,5],[49020,29,3],[49180,33,3],[49448,37,5],[50030,43,1],[50116,45,5],[50650,51,2],[50814,54,5],[52588,61,8],[53362,70,4],[53750,75,3],[54029,79,6],[54478,86,5],[55296,93,1],[55395,95,1],[55493,97,5],[55869,103,4],[56347,108,3],[56686,112,8],[58709,122,1],[58783,124,3],[59113,128,5],[59563,134,9],[61514,145,1],[61613,147,8],[62184,156,5],[62645,162,1],[62723,164,9],[63511,174,2],[63659,177,7],[64363,185,3],[64613,189,1],[64690,191,9],[65566,201,2],[65708,204,8],[66582,213,2],[66742,216,4],[67026,221,5],[67476,227,2],[67613,230,8]]]]},"os-lugares-a-mesa":{"audio":"audio/os-lugares-a-mesa.mp3?v=d9d05d2c1191","quadros":[[0,"Na casa de um fariseu, Jesus observa como os convidados escolhem os lugares de honra. Imagina alguém que toma o melhor assento numa festa. Se chegar um convidado a quem o anfitrião quer honrar mais, a pessoa terá que ceder o lugar diante de todos.",[[109,0,2],[279,3,4],[776,8,2],[919,11,2],[1061,14,7],[2099,23,5],[2707,29,7],[3479,37,4],[3849,42,2],[4024,45,10],[4935,56,8],[5622,65,2],[5797,68,7],[6427,76,2],[6624,79,5],[8108,86,7],[8813,94,6],[9250,101,3],[9443,105,4],[9845,110,1],[9907,112,6],[10350,119,7],[10950,127,4],[11269,132,5],[13063,139,2],[13296,142,6],[13760,149,2],[13917,152,9],[14739,162,1],[14834,164,4],[15124,169,1],[15203,171,9],[15956,181,4],[16259,186,6],[16651,193,4],[17457,199,1],[17569,201,6],[18109,208,4],[18458,213,3],[18628,217,5],[19088,223,1],[19162,225,5],[19595,231,6],[20143,238,2],[20315,241,5]]],[22117,"Jesus sugere tomar um lugar mais discreto e deixar que o anfitrião decida onde cada pessoa se sentará. Se ele convidar alguém a se aproximar, a honra que essa pessoa recebe já vem de fora. Jesus liga a cena à humildade de quem dispensa disputar o primeiro lugar.",[[22117,0,5],[22715,6,6],[23285,13,5],[23722,19,2],[23877,22,5],[24324,28,4],[24695,33,8],[25544,42,1],[25648,44,6],[26184,51,3],[26345,55,1],[26426,57,9],[27168,67,6],[27701,74,4],[28049,79,4],[28485,84,6],[29053,91,2],[29244,94,7],[30969,103,2],[31189,106,3],[31422,110,8],[32052,119,6],[32466,126,1],[32540,128,2],[32745,131,9],[33923,142,1],[34065,144,5],[34381,150,3],[34607,154,4],[34935,159,6],[35466,166,6],[36124,173,2],[36326,176,3],[36595,180,2],[36745,183,4],[38397,189,5],[39004,195,4],[39414,200,1],[39488,202,4],[39976,207,1],[40056,209,9],[40834,219,2],[40989,222,4],[41280,227,8],[42054,236,8],[42749,245,1],[42836,247,8],[43439,256,5]]],[45171,"Depois, Jesus fala ao anfitrião sobre a lista de convidados. Amigos e vizinhos ricos podem retribuir. Quem vive na pobreza ou enfrenta limitações físicas talvez jamais possa oferecer um jantar em troca. Jesus chama a acolher essas pessoas e põe a recompensa nas mãos de Deus.",[[45171,0,6],[46217,8,5],[46846,14,4],[47279,19,2],[47440,22,9],[48190,32,5],[48649,38,1],[48736,40,5],[49245,46,2],[49412,49,10],[51573,61,6],[52215,68,1],[52320,70,8],[53039,79,5],[53634,85,5],[54092,91,9],[56257,102,4],[56565,107,4],[56936,112,2],[57110,115,7],[57857,123,2],[58060,126,8],[58794,135,10],[59738,146,7],[60423,154,6],[61083,161,6],[61672,168,5],[62163,174,8],[62895,183,2],[63051,186,6],[63553,193,2],[63725,196,5],[65407,203,5],[66014,209,5],[66429,215,1],[66510,217,7],[67034,225,5],[67469,231,7],[68167,239,1],[68271,241,3],[68574,245,1],[68636,247,10],[69544,258,3],[69810,262,4],[70151,267,2],[70305,270,4]]]]},"a-torre-e-o-rei-que-vai-a-guerra":{"audio":"audio/a-torre-e-o-rei-que-vai-a-guerra.mp3?v=c7967b451a96","quadros":[[0,"Uma multidão acompanha Jesus, e ele fala do compromisso de ser discípulo. Pede que imaginem uma pessoa querendo construir uma torre. Antes de começar, ela se senta para calcular a despesa e ver se os recursos disponíveis bastam para terminar a construção.",[[105,0,3],[311,4,8],[981,13,9],[1670,23,5],[2657,30,1],[2799,32,3],[3052,36,4],[3535,41,2],[3677,44,11],[4584,56,2],[4726,59,3],[5022,63,9],[6992,74,4],[7456,79,3],[7639,83,8],[8312,92,3],[8522,96,6],[9068,103,8],[9624,112,9],[10354,122,3],[10601,126,5],[12244,133,5],[12704,139,2],[12861,142,7],[13948,151,3],[14222,155,2],[14421,158,5],[14918,164,4],[15229,169,8],[15878,178,1],[15958,180,7],[16821,188,1],[16928,190,3],[17194,194,2],[17391,197,2],[17558,200,8],[18326,209,11],[19363,221,6],[19965,228,4],[20267,233,8],[20896,242,1],[20982,244,10]]],[23044,"Se a pessoa lança os alicerces e depois fica sem meios, a torre permanece inacabada. Quem passa vê a obra começada e pode zombar de quem a deixou pela metade. A imagem torna público o custo que o construtor deixou de considerar no início.",[[23044,0,2],[23246,3,1],[23326,5,6],[23881,12,5],[24362,18,2],[24531,21,9],[25380,31,1],[25490,33,6],[26103,40,4],[26480,45,3],[26817,49,5],[27683,56,1],[27810,58,5],[28262,64,9],[29165,74,9],[31097,85,4],[31397,90,5],[31924,96,2],[32135,99,1],[32234,101,4],[32640,106,8],[33393,115,1],[33497,117,4],[33932,122,6],[34424,129,2],[34619,132,4],[34912,137,1],[34984,139,6],[35513,146,4],[35833,151,6],[37703,159,1],[37803,161,6],[38453,168,5],[38953,174,7],[39678,182,1],[39765,184,5],[40377,190,3],[40563,194,1],[40638,196,10],[41492,207,6],[42021,214,2],[42181,217,10],[43022,228,2],[43182,231,6]]],[44952,"Jesus imagina também um rei que avalia se pode enfrentar, com dez mil homens, um exército duas vezes maior. Se não pode, envia mensageiros para negociar a paz. As duas imagens convidam a considerar o custo real de seguir Jesus e a disposição de abrir mão dos próprios bens.",[[44952,0,5],[45530,6,7],[46225,14,6],[46705,21,2],[46912,24,3],[47200,28,3],[47413,32,6],[47935,39,2],[48143,42,4],[48570,47,9],[49719,58,3],[49982,62,3],[50326,66,3],[50579,70,6],[51447,78,2],[51640,81,8],[52519,90,4],[52949,95,5],[53409,101,5],[55173,108,2],[55380,111,3],[55618,115,4],[56485,121,5],[56895,127,11],[57899,139,4],[58185,144,8],[58888,153,1],[58993,155,3],[60627,160,2],[60840,163,4],[61209,168,7],[61927,176,8],[62600,185,1],[62673,187,10],[63475,198,1],[63562,200,5],[64147,206,4],[64578,211,2],[64720,214,6],[65193,221,5],[65772,227,1],[65878,229,1],[65953,231,10],[66935,242,2],[67108,245,5],[67534,251,3],[67847,255,3],[68117,259,8],[68857,268,4]]]]},"o-servo-que-volta-do-campo":{"audio":"audio/o-servo-que-volta-do-campo.mp3?v=8291a6cad59e","quadros":[[0,"Jesus descreve um servo que volta do campo depois de arar ou cuidar do rebanho. A cena parte das relações de trabalho conhecidas pelos ouvintes. Ao chegar à casa do senhor, ele ainda tem uma tarefa a cumprir antes de se sentar para comer.",[[112,0,5],[669,6,8],[1432,15,2],[1575,18,5],[2177,24,3],[2370,28,5],[2887,34,2],[3042,37,5],[3537,43,6],[4084,50,2],[4259,53,4],[4605,58,2],[4778,61,6],[5311,68,2],[5441,71,7],[7217,80,1],[7302,82,4],[7796,87,5],[8366,93,3],[8628,97,8],[9406,106,2],[9574,109,8],[10229,118,10],[11131,129,5],[11545,135,8],[13581,145,2],[13748,148,6],[14242,155,1],[14341,157,4],[14795,162,2],[14926,165,6],[15825,173,3],[16072,177,5],[16524,183,3],[16757,187,3],[16974,191,6],[17616,198,1],[17696,200,7],[18225,208,5],[18712,214,2],[18862,217,2],[19067,220,6],[19640,227,4],[19960,232,5]]],[21697,"O senhor pede que o servo prepare a refeição e sirva à mesa. Jesus pergunta se o senhor agradece ao servo pelo cumprimento de uma ordem. Na rotina que a parábola descreve, o homem continua o serviço que lhe foi confiado.",[[21697,0,1],[21771,2,6],[22211,9,4],[22701,14,3],[22862,18,1],[22918,20,5],[23529,26,7],[24145,34,1],[24207,36,8],[25020,45,1],[25095,47,5],[25631,53,1],[25710,55,4],[27344,61,5],[27952,67,8],[28676,76,2],[28873,79,1],[28929,81,6],[29351,88,8],[30141,97,2],[30270,100,5],[30915,106,4],[31251,111,11],[32121,123,2],[32270,126,3],[32493,130,5],[34091,137,2],[34228,140,6],[34820,147,3],[34982,151,1],[35051,153,8],[35761,162,8],[36981,172,1],[37124,174,5],[37503,180,8],[38211,189,1],[38285,191,7],[39039,199,3],[39200,203,3],[39349,207,3],[39640,211,8]]],[41587,"Só depois de servir o senhor, o trabalhador também pode comer e beber. Jesus aplica a cena aos discípulos. Depois de fazerem o que lhes foi pedido, continuam sendo servos que cumpriram seu dever. A obediência dispensa a pretensão de transformar cada serviço em crédito diante de Deus.",[[41587,0,2],[41866,3,6],[42424,10,2],[42562,13,6],[43124,20,1],[43199,22,6],[44104,30,1],[44228,32,11],[45070,44,6],[45598,51,4],[45999,56,5],[46438,62,1],[46543,64,5],[48271,71,5],[48849,77,6],[49503,84,1],[49578,86,4],[50062,91,3],[50260,95,10],[52428,107,6],[52965,114,2],[53113,117,7],[53791,125,1],[53871,127,3],[54031,131,4],[54311,136,3],[54571,140,6],[55530,148,9],[56265,158,5],[56701,164,6],[57334,171,3],[57502,175,9],[58181,185,3],[58460,189,5],[60201,196,1],[60300,198,10],[61187,209,8],[62010,218,1],[62085,220,9],[62911,230,2],[63080,233,11],[63958,245,4],[64400,250,7],[65169,258,2],[65325,261,7],[66009,269,6],[66549,276,2],[66711,279,4]]]]},"o-rico-insensato":{"audio":"audio/o-rico-insensato.mp3?v=ecf0963a3c35","quadros":[[0,"Um homem pede a Jesus que intervenha numa disputa de herança. Jesus adverte sobre a ganância e fala de outro homem, já rico, cuja terra produz muito. Com uma colheita tão grande, o proprietário se pergunta onde poderá guardar tudo.",[[107,0,2],[284,3,5],[669,9,4],[1068,14,1],[1142,16,5],[1739,22,3],[1906,26,10],[2578,37,4],[2886,42,7],[3643,50,2],[3818,53,7],[5536,62,5],[6114,68,7],[6830,76,5],[7275,82,1],[7348,84,8],[8178,93,1],[8284,95,4],[8770,100,2],[8932,103,5],[9378,109,5],[10103,116,2],[10327,119,4],[11177,125,4],[11643,130,5],[12099,136,6],[12732,143,5],[14443,150,3],[14703,154,3],[14939,158,8],[15622,167,3],[15915,171,6],[16782,179,1],[16874,181,12],[17872,194,2],[18072,197,8],[18816,206,4],[19146,211,6],[19685,218,7],[20265,226,4]]],[21831,"O homem planeja derrubar os celeiros e construir outros maiores. Quando o cereal e os bens estiverem guardados, espera descansar, comer e beber por muitos anos. Seu plano responde à falta de espaço e transforma a abundância acumulada em garantia para o futuro.",[[21831,0,1],[21960,2,5],[22334,8,7],[22996,16,8],[23577,25,2],[23714,28,8],[24343,37,1],[24448,39,9],[25196,49,6],[25729,56,7],[27698,65,6],[28094,72,1],[28150,74,6],[28762,81,1],[28898,83,2],[29078,86,4],[29470,91,9],[30187,101,9],[31406,112,6],[31987,119,9],[33243,130,5],[33711,136,1],[33816,138,5],[34246,144,3],[34480,148,6],[35084,155,4],[36746,161,3],[37046,165,5],[37527,171,8],[38314,180,1],[38394,182,5],[38965,188,2],[39126,191,6],[39935,198,1],[40034,200,10],[40943,211,1],[41025,213,10],[41837,224,9],[42698,234,2],[42840,237,8],[43579,246,4],[43876,251,1],[43938,253,6]]],[45705,"Deus lhe diz que naquela mesma noite sua vida será requerida. Surge então a pergunta sobre quem ficará com o que ele preparou. Jesus termina a história distinguindo o acúmulo para si da riqueza diante de Deus. Os celeiros podem ficar cheios quando a vida já terminou.",[[45705,0,4],[46068,5,3],[46238,9,3],[46610,13,3],[46758,17,7],[47332,25,5],[47855,31,5],[48358,37,3],[48678,41,4],[49097,46,4],[49478,51,9],[51287,62,5],[51860,68,5],[52293,74,1],[52368,76,8],[53105,85,5],[53573,91,4],[53840,96,6],[54397,103,3],[54661,107,1],[54736,109,3],[54966,113,3],[55219,117,8],[57075,127,5],[57705,133,7],[58286,141,1],[58354,143,8],[58943,152,12],[59773,165,1],[59853,167,7],[60532,175,4],[60820,180,2],[61040,183,2],[61184,186,7],[61873,194,6],[62412,201,2],[62567,204,4],[64220,210,2],[64374,213,8],[64994,222,5],[65447,228,5],[65934,234,6],[66504,241,6],[66896,248,1],[67002,250,4],[67447,255,2],[67643,258,8]]]]},"o-administrador-astuto":{"audio":"audio/o-administrador-astuto.mp3?v=7362f270b537","quadros":[[0,"Um homem rico recebe a acusação de que seu administrador desperdiça os bens da propriedade. Pede uma prestação de contas e avisa que ele perderá o cargo. O administrador pensa no que fará sem o trabalho e procura um modo de ser recebido por outras pessoas.",[[110,0,2],[290,3,5],[665,9,4],[1108,14,6],[1757,21,1],[1843,23,8],[2634,32,2],[2801,35,3],[2958,39,3],[3258,43,13],[4312,57,10],[5215,68,2],[5388,71,4],[5794,76,2],[5958,79,11],[8142,92,4],[8555,97,3],[8765,101,9],[9610,111,2],[9777,114,6],[10389,121,1],[10494,123,5],[11015,129,3],[11195,133,3],[11424,137,7],[11984,145,1],[12070,147,5],[13766,154,1],[13858,156,13],[14911,170,5],[15427,176,2],[15582,179,3],[15742,183,4],[16137,188,3],[16498,192,1],[16572,194,8],[17271,203,1],[17377,205,7],[17986,213,2],[18157,216,4],[18589,221,2],[18724,224,3],[19021,228,8],[19839,237,3],[20066,241,6],[20600,248,7]]],[22616,"Ele chama os devedores do senhor. Ao que deve azeite, manda reduzir o valor escrito à metade. Ao que deve trigo, manda registrar oitenta em vez de cem. Usa o tempo que ainda tem no cargo para preparar seu futuro por meio dessas dívidas.",[[22616,0,3],[22843,4,5],[23276,10,2],[23445,13,9],[24230,23,2],[24367,26,6],[26173,34,2],[26346,37,3],[26528,41,4],[26938,46,6],[27969,54,5],[28418,60,7],[29057,68,1],[29133,70,5],[29577,76,7],[30288,84,1],[30367,86,6],[32226,94,2],[32398,97,3],[32580,101,4],[32989,106,5],[33844,113,5],[34289,119,9],[35105,129,7],[35769,137,2],[35919,140,3],[36178,144,2],[36345,147,3],[37887,152,3],[38242,156,1],[38335,158,5],[38837,164,3],[39023,168,5],[39476,174,3],[39733,178,2],[39901,181,5],[40430,187,4],[40745,192,8],[41429,201,3],[41696,205,6],[42296,212,3],[42519,216,4],[42904,221,6],[43442,228,7]]],[45356,"O senhor reconhece a esperteza do administrador, cuja conduta a história chama de injusta. Jesus usa a habilidade de prever consequências para falar do uso das riquezas. O ensino termina com a fidelidade nas pequenas coisas e com a impossibilidade de servir ao mesmo tempo a Deus e ao dinheiro.",[[45356,0,1],[45430,2,6],[45881,9,9],[46760,19,1],[46834,21,9],[47758,31,2],[47905,34,13],[49359,49,4],[49774,54,7],[50442,62,1],[50509,64,8],[51111,73,5],[51580,79,2],[51761,82,7],[53622,91,5],[54230,97,3],[54609,101,1],[54690,103,10],[55510,114,2],[55670,117,6],[56190,124,13],[57310,138,4],[57606,143,5],[58109,149,2],[58299,152,3],[58640,156,3],[58901,160,8],[60929,170,1],[61021,172,6],[61571,179,7],[62153,187,3],[62408,191,1],[62470,193,10],[63401,204,3],[63636,208,8],[64336,217,6],[64945,224,1],[65050,226,3],[65311,230,1],[65416,232,15],[66610,248,2],[66760,251,6],[67315,258,2],[67463,261,5],[67992,267,5],[68507,273,1],[68599,275,4],[68999,280,1],[69113,282,2],[69270,285,8]]]]},"o-rico-e-lazaro":{"audio":"audio/o-rico-e-lazaro.mp3?v=6bda3e2c57d0","quadros":[[0,"Jesus descreve um homem rico que se veste com luxo e faz grandes refeições. Junto ao portão dele está Lázaro, pobre e coberto de feridas. Lázaro gostaria de comer o que cai da mesa. Os cães se aproximam e lambem suas feridas.",[[112,0,5],[669,6,8],[1438,15,2],[1594,18,5],[1972,24,4],[2440,29,3],[2602,33,2],[2820,36,5],[3382,42,3],[3623,46,4],[4229,51,1],[4326,53,3],[4698,57,7],[5288,65,9],[7468,76,5],[7962,82,2],[8085,85,6],[8669,92,4],[9069,97,4],[9426,102,6],[10420,110,5],[10999,116,1],[11106,118,7],[11805,126,2],[11967,129,7],[13909,138,6],[14502,145,8],[15163,154,2],[15339,157,5],[15766,163,1],[15852,165,3],[16036,169,3],[16338,173,2],[16501,176,4],[18123,182,2],[18334,185,4],[18727,190,2],[18897,193,9],[19769,203,1],[19873,205,6],[20275,212,4],[20669,217,7]]],[22580,"Lázaro morre e é levado pelos anjos para junto de Abraão. O rico também morre. Em tormento, vê Lázaro de longe e pede que ele lhe leve um pouco de água. Abraão lembra a diferença entre as vidas dos dois e diz que um abismo impede a travessia.",[[22580,0,6],[23178,7,5],[23652,13,1],[23789,15,1],[23931,17,6],[24556,24,5],[24998,30,5],[25509,36,4],[25857,41,5],[26358,47,2],[26539,50,6],[28267,58,1],[28341,60,4],[28801,65,6],[29288,72,5],[30891,79,2],[31074,82,8],[32168,92,2],[32396,95,6],[32987,102,2],[33154,105,5],[33694,111,1],[33801,113,4],[34269,118,3],[34446,122,3],[34633,126,3],[34789,130,4],[35213,135,2],[35393,138,5],[35928,144,2],[36126,147,4],[37678,153,6],[38220,160,6],[38698,167,1],[38773,169,9],[39659,179,5],[40022,185,2],[40219,188,5],[40712,194,3],[40959,198,4],[41357,203,1],[41444,205,3],[41819,209,3],[41956,213,2],[42118,216,6],[42713,223,6],[43253,230,1],[43328,232,9]]],[45285,"O rico pede que Lázaro vá avisar seus irmãos. Abraão responde que eles já têm Moisés e os profetas para ouvir. A história termina chamando a prestar atenção às Escrituras enquanto é possível agir. O sofrimento que estava todos os dias junto ao portão já exigia uma resposta.",[[45285,0,1],[45359,2,4],[45826,7,4],[46294,12,3],[46454,16,6],[47077,23,2],[47330,26,6],[47859,33,4],[48239,38,6],[50054,46,6],[50596,53,8],[51386,62,3],[51569,66,4],[51839,71,2],[52036,74,3],[52313,78,6],[52965,85,1],[53069,87,2],[53235,90,8],[54071,99,4],[54385,104,5],[56137,111,1],[56236,113,8],[56858,122,7],[57428,130,8],[58083,139,1],[58166,141,7],[58746,149,7],[59403,157,2],[59607,160,10],[60495,171,8],[61117,180,1],[61259,182,8],[62004,191,4],[63704,197,1],[63778,199,10],[64717,210,3],[64877,214,6],[65467,221,5],[66040,227,2],[66195,230,4],[66623,235,5],[67139,241,2],[67262,244,6],[67858,251,2],[68047,254,6],[68648,261,3],[68849,265,8]]]]},"os-servos-vigilantes":{"audio":"audio/os-servos-vigilantes.mp3?v=58a0654e981f","quadros":[[0,"Em Lucas, Jesus pede que os discípulos se imaginem como servos com as roupas ajustadas para o trabalho e as lâmpadas acesas. Eles aguardam o senhor voltar de uma festa de casamento. Permanecem prontos para abrir a porta assim que ele chamar.",[[108,0,2],[267,3,5],[1172,10,5],[1789,16,4],[2253,21,3],[2392,25,2],[2529,28,10],[3469,39,2],[3639,42,8],[4296,51,4],[4628,56,6],[5261,63,3],[5497,67,2],[5708,70,6],[6328,77,9],[7158,87,4],[7442,92,1],[7515,94,8],[8219,103,1],[8361,105,2],[8558,108,8],[9262,117,6],[11166,125,4],[11499,130,8],[12287,139,1],[12350,141,6],[12794,148,6],[13325,155,2],[13480,158,3],[13697,162,5],[14313,168,2],[14480,171,9],[16525,182,10],[17496,193,7],[18147,201,4],[18435,206,5],[18830,212,1],[18940,214,5],[19522,220,5],[19965,226,3],[20142,230,3],[20329,234,6]]],[22177,"A volta pode acontecer tarde da noite ou já perto da madrugada. Quem espera desconhece a hora. Em Marcos, Jesus imagina também um senhor que viaja, deixa os servos com suas tarefas e manda o porteiro vigiar. Cada um deve cuidar do que lhe foi confiado.",[[22177,0,1],[22287,2,5],[22830,8,4],[23250,13,9],[24039,23,5],[24592,29,2],[24749,32,5],[25255,38,2],[25434,41,2],[25619,44,5],[26131,50,2],[26276,53,9],[28272,64,4],[28560,69,6],[29129,76,10],[30042,87,1],[30142,89,4],[31639,95,2],[31801,98,6],[32836,106,5],[33433,112,7],[34130,120,6],[34601,127,2],[34755,130,6],[35234,137,3],[35412,141,5],[36340,148,5],[36832,154,2],[36975,157,6],[37550,164,3],[37781,168,4],[38200,173,7],[38944,181,1],[39049,183,5],[39519,189,1],[39594,191,8],[40277,200,6],[42127,208,4],[42499,213,2],[42649,216,4],[43086,221,6],[43603,228,2],[43746,231,3],[43896,235,3],[44046,239,3],[44338,243,8]]],[46294,"No relato de Lucas, o senhor encontra os servos acordados. Para surpresa deles, ele próprio se prepara, manda que se reclinem à mesa e os serve. A alegria dessa volta dá sentido à espera. Jesus conclui pedindo preparo, porque a chegada do Filho do Homem será inesperada.",[[46294,0,2],[46432,3,6],[47045,10,2],[47213,13,5],[48149,20,1],[48235,22,6],[48664,29,8],[49304,38,2],[49453,41,6],[49976,48,9],[51985,59,4],[52394,64,8],[53231,73,5],[54116,80,3],[54372,84,7],[55020,92,2],[55218,95,7],[56248,104,5],[56697,110,3],[56865,114,2],[57052,117,8],[57700,126,1],[57806,128,4],[58349,133,1],[58455,135,2],[58617,138,5],[60324,145,1],[60415,147,7],[61056,155,5],[61555,161,5],[62146,167,2],[62338,170,7],[63070,178,1],[63151,180,6],[64961,188,5],[65569,194,7],[66181,202,7],[66792,210,7],[67860,219,6],[68268,226,1],[68344,228,7],[68992,236,2],[69128,239,5],[69593,245,2],[69788,248,5],[70128,254,4],[70508,259,10]]]]},"o-administrador-fiel-e-o-abusivo":{"audio":"audio/o-administrador-fiel-e-o-abusivo.mp3?v=af232277bdb6","quadros":[[0,"Um senhor confia a um administrador o cuidado das pessoas de sua casa. Cabe a ele distribuir o alimento no momento certo. Jesus chama feliz o servo que o senhor, ao voltar, encontrar fazendo esse trabalho. A confiança se mede pela forma como ele cuida dos outros.",[[108,0,2],[251,3,6],[692,10,6],[1322,17,1],[1399,19,2],[1555,22,13],[2611,36,1],[2704,38,7],[3365,46,3],[3626,50,7],[4253,58,2],[4395,61,3],[4717,65,4],[6391,71,4],[6811,76,1],[6909,78,3],[7191,82,10],[8039,93,1],[8120,95,8],[8761,104,2],[8911,107,7],[9506,115,5],[11348,122,5],[11955,128,5],[12345,134,5],[12861,140,1],[12935,142,5],[13555,148,3],[13739,152,1],[13806,154,6],[14705,162,2],[14880,165,6],[15825,173,9],[16546,183,7],[17198,191,4],[17535,196,8],[19342,206,1],[19433,208,9],[20253,218,2],[20445,221,4],[20862,226,4],[21194,231,5],[21813,237,4],[22193,242,3],[22465,246,5],[22974,252,3],[23243,256,6]]],[25062,"Jesus imagina o que acontece se o administrador presume que o senhor vai demorar. Ele começa a espancar os outros servos, come e bebe em excesso. O cargo que lhe foi entregue para manter a casa passa a servir aos seus próprios desejos.",[[25062,0,5],[25640,6,7],[26347,14,1],[26422,16,3],[26627,20,8],[27421,29,2],[27626,32,1],[27713,34,13],[28743,48,7],[29329,56,3],[29491,60,1],[29541,62,6],[30009,69,3],[30280,73,7],[32146,82,3],[32389,86,6],[33048,93,1],[33116,95,8],[33790,104,2],[33982,107,6],[34483,114,6],[35396,122,4],[35812,127,1],[35920,129,4],[36349,134,2],[36521,137,7],[38364,146,1],[38463,148,5],[38993,154,3],[39153,158,3],[39302,162,3],[39592,166,8],[40213,175,4],[40507,180,6],[40951,187,1],[41063,189,4],[41577,194,5],[42133,200,1],[42212,202,6],[42752,209,3],[42965,213,4],[43322,218,8],[44033,227,7]]],[46028,"O senhor volta em dia e hora inesperados e pune o abuso. Em Lucas, Jesus acrescenta que se pede mais de quem recebeu mais. A espera pela volta expõe a responsabilidade de quem tem autoridade, especialmente quando pode decidir como tratar os outros sem ser observado.",[[46028,0,1],[46102,2,6],[46541,9,5],[47102,15,2],[47255,18,3],[47632,22,1],[47737,24,4],[48051,29,11],[49006,41,1],[49111,43,4],[49509,48,1],[49589,50,5],[51319,57,2],[51478,60,5],[52400,67,5],[53003,73,10],[53807,84,3],[53969,88,2],[54174,91,4],[54574,96,4],[54937,101,2],[55087,104,4],[55372,109,7],[56022,117,4],[57672,123,1],[57771,125,6],[58353,132,4],[58722,137,5],[59224,143,5],[59691,149,1],[59753,151,16],[61200,168,2],[61355,171,4],[61664,176,3],[61930,180,10],[63212,192,13],[64418,206,6],[64832,213,4],[65243,218,7],[65907,226,4],[66292,231,6],[66817,238,2],[67009,241,6],[67609,248,3],[67868,252,3],[68150,256,9]]]]},"as-dez-virgens":{"audio":"audio/as-dez-virgens.mp3?v=cb9fe8635945","quadros":[[0,"Dez jovens levam lâmpadas para esperar o noivo. Cinco carregam óleo de reserva, e cinco levam apenas as lâmpadas. Como o noivo demora, todas ficam sonolentas e adormecem. A diferença entre elas só aparece quando chega a hora de sair.",[[106,0,3],[389,4,6],[1009,11,5],[1462,17,8],[2229,26,4],[2529,31,7],[3122,39,1],[3209,41,5],[4886,48,5],[5427,54,8],[6111,63,4],[6465,68,2],[6625,71,7],[7756,80,1],[7841,82,5],[8392,88,5],[8880,94,6],[9464,101,2],[9661,104,8],[11632,114,4],[11994,119,1],[12078,121,5],[12562,127,6],[13476,135,5],[14070,141,5],[14502,147,10],[15364,158,1],[15469,160,9],[17412,171,1],[17504,173,9],[18383,183,5],[18791,189,4],[19173,194,2],[19403,197,7],[20093,205,6],[20492,212,5],[20966,218,1],[21066,220,4],[21421,225,2],[21571,228,4]]],[23324,"À meia-noite, alguém anuncia a chegada do noivo. As jovens se levantam e preparam as lâmpadas. As que estão sem óleo pedem às outras que repartam a reserva. Como talvez não haja o suficiente para todas, saem para tentar comprar mais.",[[23324,0,1],[23416,2,10],[24686,14,6],[25146,21,7],[25769,29,1],[25843,31,7],[26452,39,2],[26608,42,5],[28264,49,2],[28446,52,6],[29086,59,2],[29256,62,8],[29935,71,1],[30040,73,8],[30705,82,2],[30915,85,8],[32880,95,2],[33085,98,3],[33234,102,5],[33702,108,3],[34050,112,4],[34416,117,5],[34880,123,2],[35132,126,6],[35729,133,3],[35878,137,8],[36555,146,1],[36617,148,7],[38516,157,4],[38878,162,6],[39551,169,3],[39808,173,4],[40168,178,1],[40243,180,10],[41201,191,4],[41543,196,5],[42509,203,4],[42961,208,4],[43267,213,6],[43777,220,7],[44423,228,4]]],[46058,"Enquanto elas estão fora, o noivo chega. As que estavam prontas entram para as bodas, e a porta se fecha. Quando as outras voltam, pedem para entrar. A festa já começou. Jesus encerra chamando a vigiar, pois ninguém sabe o dia nem a hora.",[[46058,0,8],[46674,9,4],[47021,14,5],[47446,20,4],[48285,26,1],[48378,28,5],[48861,34,5],[50522,41,2],[50726,44,3],[50876,48,7],[51503,56,7],[52123,64,6],[52623,71,4],[52892,76,2],[53092,79,5],[54071,86,1],[54171,88,1],[54270,90,5],[54799,96,2],[55009,99,5],[56707,106,6],[57136,113,2],[57326,116,6],[57885,123,6],[58832,131,5],[59335,137,4],[59646,142,6],[61455,150,1],[61557,152,5],[62201,158,2],[62402,161,7],[64282,170,5],[64859,176,7],[65514,184,8],[66170,193,1],[66245,195,6],[67199,203,4],[67659,208,7],[68191,216,4],[68665,221,1],[68753,223,3],[69109,227,3],[69371,231,1],[69471,233,4]]]]},"os-talentos":{"audio":"audio/os-talentos.mp3?v=3ebbf47df58f","quadros":[[0,"Antes de viajar, um homem deixa seus bens com três servos. Entrega cinco talentos a um, dois a outro e um ao terceiro, conforme a capacidade de cada um. Um talento representa uma grande quantia. Cada servo precisa decidir o que fazer com o que recebeu.",[[111,0,5],[518,6,2],[671,9,6],[1648,17,2],[1847,20,5],[2239,26,5],[2745,32,4],[3139,37,4],[3559,42,3],[3819,46,4],[4190,51,6],[5974,59,7],[6630,67,5],[7216,73,8],[7935,82,1],[8068,84,2],[8648,88,4],[9064,93,1],[9195,95,5],[9764,101,1],[9903,103,2],[10069,106,2],[10237,109,8],[11319,119,8],[12098,128,1],[12174,130,10],[13216,141,2],[13394,144,4],[13823,149,2],[15191,153,2],[15376,156,7],[16009,164,10],[16884,175,3],[17121,179,6],[17631,186,7],[19556,195,4],[19972,200,5],[20585,206,7],[21286,214,7],[21939,222,1],[22026,224,3],[22186,228,5],[22646,234,3],[22906,238,1],[22984,240,3],[23144,244,7]]],[25020,"Os dois primeiros negociam e duplicam os valores. O terceiro cava um buraco e esconde o dinheiro na terra. Mais tarde, ele explica que teve medo do senhor. Ao guardar a quantia intacta, protege o que recebeu de uma perda, mas deixa de fazer qualquer uso dela.",[[25020,0,2],[25221,3,4],[25625,8,9],[26306,18,8],[27109,27,1],[27218,29,8],[27808,38,2],[27957,41,7],[29851,50,1],[29960,52,8],[30656,61,4],[31109,66,2],[31260,69,6],[31959,76,1],[32100,78,7],[32768,86,1],[32843,88,8],[33425,97,2],[33610,100,5],[35230,107,4],[35645,112,5],[36534,119,3],[36769,123,7],[37470,131,3],[37665,135,4],[38051,140,4],[38439,145,2],[38570,148,6],[40371,156,2],[40538,159,7],[41092,167,1],[41178,169,7],[41833,177,7],[42903,186,7],[43619,194,1],[43692,196,3],[43852,200,7],[44504,208,2],[44654,211,3],[44880,215,5],[45758,222,3],[46073,226,5],[46577,232,2],[46739,235,5],[47194,241,8],[47814,250,3],[48204,254,4]]],[49743,"Muito tempo depois, o senhor volta e pede contas. Recebe os dois primeiros com o mesmo elogio e os convida a participar de sua alegria. Repreende o servo que devolve apenas a quantia enterrada. Jesus liga a espera à responsabilidade de agir com o que foi confiado.",[[49743,0,5],[50177,6,5],[50635,12,6],[51679,20,1],[51767,22,6],[52200,29,5],[52767,35,1],[52866,37,4],[53300,42,6],[55190,50,6],[55862,57,2],[56047,60,4],[56447,65,9],[57217,75,3],[57458,79,1],[57533,81,5],[58067,87,6],[58692,94,1],[58837,96,2],[59009,99,7],[59537,107,1],[59611,109,10],[60527,120,2],[60707,123,3],[61011,127,7],[62806,136,9],[63544,146,1],[63619,148,5],[64244,154,3],[64404,158,7],[65076,166,6],[65668,173,1],[65755,175,7],[66407,183,9],[68191,194,5],[68799,200,4],[69209,205,1],[69278,207,6],[69882,214,1],[69968,216,16],[71428,233,2],[71601,236,4],[72008,241,3],[72258,245,1],[72335,247,3],[72511,251,3],[72799,255,8]]]]},"as-minas":{"audio":"audio/as-minas.mp3?v=c048cf2a5680","quadros":[[0,"Perto de Jerusalém, alguns pensam que o Reino de Deus vai se manifestar imediatamente. Jesus conta que um homem de origem nobre viaja para receber autoridade de rei. Antes de partir, chama dez servos, entrega a cada um uma mina e manda que negociem enquanto ele estiver fora.",[[107,0,5],[602,6,2],[763,9,9],[1889,20,6],[2429,27,6],[2990,34,3],[3151,38,1],[3238,40,5],[3727,46,2],[3879,49,4],[4282,54,3],[4538,58,2],[4736,61,10],[5623,72,13],[8000,87,5],[8607,93,5],[9059,99,3],[9207,103,2],[9368,106,5],[9741,112,2],[9916,115,6],[10478,122,5],[10968,128,5],[11534,134,4],[11830,139,7],[12470,147,10],[13346,158,2],[13513,161,3],[14980,166,5],[15390,172,2],[15537,175,6],[16529,183,5],[16994,189,3],[17291,193,6],[18197,201,7],[18873,209,1],[18973,211,4],[19370,216,2],[19530,219,3],[19739,223,4],[20161,228,1],[20266,230,5],[20719,236,3],[20887,240,8],[21570,249,8],[22182,258,3],[22399,262,7],[22984,270,4]]],[24619,"Os cidadãos que rejeitam o homem enviam uma delegação para protestar. Mesmo assim, ele regressa com autoridade e pede contas aos servos. Um deles fez sua mina render dez. Outro fez render cinco. Ambos recebem responsabilidade sobre cidades em proporção ao resultado.",[[24619,0,2],[24761,3,8],[25474,12,3],[25629,16,8],[26312,25,1],[26412,27,5],[26804,33,6],[27222,40,3],[27412,44,9],[28212,54,4],[28507,59,9],[30631,70,5],[31112,76,5],[31925,83,3],[32170,87,8],[32771,96,3],[33025,100,10],[34034,111,1],[34138,113,4],[34564,118,6],[35143,125,3],[35366,129,6],[37125,137,2],[37303,140,5],[37805,146,3],[38085,150,3],[38379,154,4],[38739,159,6],[39302,166,4],[40898,171,5],[41347,177,3],[41669,181,6],[42159,188,5],[43912,195,5],[44353,201,7],[45065,209,16],[46540,226,5],[46991,232,7],[47748,240,2],[47902,243,9],[48717,253,2],[48860,256,9]]],[50954,"Outro servo devolve a mina que guardou num pano. Alega medo da severidade do senhor, que pergunta por que ele nem sequer pôs o dinheiro a render. Seu valor é entregue a outro. A história situa a responsabilidade dos servos no tempo de espera pela volta.",[[50954,0,5],[51377,6,5],[51978,12,7],[52657,20,1],[52744,22,4],[53120,27,3],[53289,31,7],[53888,39,3],[54158,43,4],[55746,49,5],[56264,55,4],[56702,60,2],[56857,63,10],[57814,74,2],[57944,77,6],[58847,85,3],[59038,89,8],[59773,98,3],[60014,102,3],[60237,106,3],[60492,110,3],[60766,114,6],[61277,121,3],[61664,125,1],[61744,127,8],[62332,136,1],[62394,138,6],[64165,146,3],[64471,150,5],[64916,156,1],[65051,158,8],[65676,167,1],[65775,169,5],[67465,176,1],[67564,178,8],[68141,187,5],[68702,193,1],[68764,195,16],[70224,212,3],[70445,216,6],[71009,223,2],[71196,226,5],[71692,232,2],[71848,235,6],[72426,242,4],[72798,247,5]]]]},"as-ovelhas-e-os-bodes":{"audio":"audio/as-ovelhas-e-os-bodes.mp3?v=8f8716957b0e","quadros":[[0,"Jesus descreve a vinda do Filho do Homem em glória. Todas as nações se reúnem diante dele. Como um pastor que separa ovelhas de bodes, ele põe um grupo à direita e o outro à esquerda. A explicação começa com gestos comuns da vida de todos os dias.",[[112,0,5],[669,6,8],[1454,15,1],[1559,17,5],[2039,23,2],[2174,26,5],[2639,32,2],[2827,35,5],[3196,41,2],[3357,44,6],[5009,52,5],[5530,58,2],[5724,61,6],[6380,68,2],[6553,71,6],[7079,78,6],[7689,85,5],[9251,91,4],[9611,96,2],[9761,99,6],[10361,106,3],[10531,110,6],[11125,117,7],[11693,125,2],[11851,128,5],[12793,135,3],[13046,139,3],[13330,143,2],[13494,146,5],[14031,152,1],[14110,154,7],[14800,162,1],[14911,164,1],[15010,166,5],[15479,172,1],[15560,174,8],[17404,184,1],[17504,186,10],[18460,197,6],[19103,204,3],[19365,208,6],[20030,215,6],[20573,222,2],[20761,225,4],[21184,230,2],[21363,233,5],[21906,239,2],[22066,242,4]]],[23752,"O rei convida os da direita a receber o Reino. Lembra que lhe deram comida quando teve fome, água quando teve sede e abrigo quando era forasteiro. Vestiram-no e o visitaram na doença e na prisão. Surpresos, eles perguntam quando o encontraram nessas condições.",[[23752,0,1],[23826,2,3],[24146,6,7],[24654,14,2],[24839,17,2],[25000,20,7],[25636,28,1],[25696,30,7],[26356,38,1],[26436,40,5],[28130,47,6],[28584,54,3],[28744,58,3],[28911,62,5],[29314,68,6],[29914,75,6],[30343,82,4],[30734,87,4],[31591,93,4],[32004,98,6],[32420,105,4],[32797,110,4],[33404,115,1],[33546,117,6],[34153,124,6],[34556,131,3],[34863,135,10],[36976,147,11],[37777,159,1],[37919,161,1],[37987,163,9],[38752,173,2],[38921,176,6],[39636,183,1],[39724,185,2],[39898,188,6],[41620,196,9],[42882,207,4],[43238,212,9],[44028,222,6],[44425,229,1],[44498,231,11],[45332,243,6],[45875,250,9]]],[47949,"O rei explica que recebeu os gestos feitos aos menores de seus irmãos. Ao outro grupo, atribui a omissão diante dessas mesmas necessidades. Os dois grupos se surpreendem. A cena dá peso às escolhas concretas de acolher, alimentar e cuidar de quem precisa.",[[47949,0,1],[48020,2,3],[48350,6,7],[49049,14,3],[49217,18,7],[49862,26,2],[50018,29,6],[50692,36,6],[51291,43,3],[51534,47,7],[52170,55,2],[52307,58,4],[52696,63,6],[54509,71,2],[54721,74,5],[55198,80,5],[56060,87,7],[56697,95,1],[56778,97,7],[57385,105,6],[57980,112,6],[58559,119,6],[59180,126,12],[61562,140,2],[61764,143,4],[62151,148,6],[62791,155,2],[62961,158,11],[64995,171,1],[65087,173,4],[65577,178,2],[65797,181,4],[66254,186,2],[66432,189,8],[67146,198,9],[67890,208,2],[68063,211,7],[68996,220,9],[69726,230,1],[69831,232,6],[70338,239,2],[70538,242,4],[70826,247,7]]]]},"o-bom-pastor":{"audio":"audio/o-bom-pastor.mp3?v=77a09b907f2a","quadros":[[0,"Jesus descreve a entrada de um curral. O porteiro abre para o pastor, que chama suas ovelhas pelo nome e segue adiante delas. As ovelhas reconhecem sua voz e o acompanham. Ao ouvir uma voz estranha, elas se afastam.",[[112,0,5],[669,6,8],[1457,15,1],[1544,17,7],[2169,25,2],[2319,28,2],[2473,31,6],[4157,39,1],[4239,41,8],[4928,50,4],[5359,55,4],[5630,60,1],[5705,62,6],[6698,70,3],[6891,74,5],[7346,80,4],[7765,85,7],[8419,93,4],[8742,98,4],[9177,103,1],[9251,105,5],[9696,111,7],[10367,119,5],[12128,126,2],[12337,129,7],[12933,137,10],[13803,148,3],[14117,152,3],[14462,156,1],[14573,158,1],[14653,160,10],[16629,172,2],[16844,175,5],[17276,181,3],[17510,185,3],[17860,189,8],[18900,199,4],[19311,204,2],[19491,207,7]]],[21401,"Quando um lobo se aproxima, o empregado foge e deixa as ovelhas. O bom pastor fica. Jesus diz que conhece as suas ovelhas e que elas o conhecem. Ele relaciona esse cuidado à entrega da própria vida e diz que o faz por vontade própria.",[[21401,0,6],[21813,7,2],[21977,10,4],[22395,15,2],[22603,18,8],[23729,28,1],[23833,30,9],[24594,40,4],[25163,45,1],[25268,47,5],[25793,53,2],[25983,56,7],[27878,65,1],[27980,67,3],[28295,71,6],[28870,78,4],[30537,84,5],[31105,90,3],[31436,94,3],[31608,98,7],[32249,106,2],[32405,109,4],[32774,114,7],[33450,122,1],[33554,124,3],[33734,128,4],[34136,133,1],[34223,135,8],[36087,145,3],[36308,149,9],[37195,159,4],[37531,164,7],[38191,172,1],[38272,174,7],[38934,182,2],[39101,185,7],[39780,193,4],[40251,198,1],[40356,200,3],[40730,204,3],[40871,208,1],[40956,210,3],[41324,214,3],[41573,218,7],[42237,226,7]]],[44001,"Jesus se apresenta também como a porta das ovelhas, pela qual elas entram, saem e encontram pastagem. Fala de outras ovelhas que ouvirão sua voz e serão reunidas num só rebanho. Essas imagens descrevem a proteção e a vida oferecidas a quem o segue.",[[44001,0,5],[44599,6,2],[44759,9,9],[45531,19,6],[46058,26,4],[46414,31,1],[46507,33,5],[47037,39,3],[47305,43,7],[48354,52,4],[48748,57,4],[49153,62,4],[49527,67,6],[50347,75,4],[50863,80,1],[51007,82,9],[51717,92,8],[53708,102,4],[54196,107,2],[54365,110,6],[54905,117,7],[55554,125,3],[55694,129,7],[56204,137,3],[56514,141,3],[56860,145,1],[56935,147,5],[57392,153,8],[58194,162,3],[58478,166,2],[58780,169,7],[60547,178,5],[60968,184,7],[61645,192,9],[62505,202,1],[62579,204,8],[63404,213,1],[63546,215,1],[63645,217,4],[64085,222,10],[65053,233,1],[65164,235,4],[65456,240,1],[65525,242,5]]]]},"a-videira-e-os-ramos":{"audio":"audio/a-videira-e-os-ramos.mp3?v=0609b3450131","quadros":[[0,"Na sua despedida, Jesus diz aos discípulos que é a videira verdadeira e que o Pai é o agricultor. O agricultor tira o ramo sem fruto. Cuida do ramo que dá fruto, podando-o para que produza ainda mais. A lavoura ajuda a entender a relação entre Jesus, o Pai e os discípulos.",[[109,0,2],[266,3,3],[587,7,9],[1812,18,5],[2399,24,3],[2739,28,3],[2949,32,10],[3879,43,3],[4039,47,1],[4176,49,1],[4264,51,7],[4838,59,10],[5768,70,1],[5873,72,3],[6034,76,1],[6103,78,3],[6458,82,1],[6557,84,1],[6638,86,10],[8773,98,1],[8872,100,10],[9712,111,4],[10152,116,1],[10239,118,4],[10620,123,3],[10942,127,5],[12671,134,5],[13128,140,2],[13270,143,4],[13643,148,3],[13814,152,2],[13999,155,5],[14913,162,9],[15595,172,4],[15903,177,3],[16083,181,7],[16673,189,5],[17115,195,4],[18762,201,1],[18854,203,7],[19508,211,5],[20108,217,1],[20177,219,8],[20744,228,1],[20819,230,7],[21487,238,5],[21851,244,5],[22831,251,1],[22943,253,3],[23303,257,1],[23442,259,2],[23577,262,10]]],[25711,"Um ramo só pode produzir uvas enquanto estiver ligado à videira. Jesus pede aos discípulos que permaneçam nele, assim como ele permanece neles. A seiva que passa pelo ramo representa a dependência que permite produzir fruto. Separado do tronco, o ramo acaba secando.",[[25711,0,2],[25867,3,4],[26232,8,2],[26526,11,4],[26936,16,8],[27602,25,4],[28022,30,8],[28639,39,7],[29270,47,6],[29876,54,1],[29956,56,7],[31732,65,5],[32340,71,4],[32710,76,3],[32910,80,10],[33845,91,3],[34001,95,10],[34924,106,4],[35685,112,5],[36169,118,4],[36542,123,3],[36802,127,9],[37639,137,5],[39395,144,1],[39487,146,5],[40045,152,3],[40226,156,5],[40757,162,4],[41080,167,4],[41424,172,10],[42315,183,1],[42389,185,11],[43300,197,3],[43468,201,7],[44146,209,8],[44821,218,5],[46556,225,8],[47353,234,2],[47507,237,6],[48441,245,1],[48535,247,4],[48933,252,5],[49459,258,7]]],[51230,"Jesus liga o fruto ao amor que os discípulos devem ter uns pelos outros. Pede que guardem seus mandamentos e permaneçam no seu amor. Escolheu os discípulos para que vão e deem fruto duradouro. A videira torna visível de onde vem a força para cumprir esse chamado.",[[51230,0,5],[51838,6,4],[52247,11,1],[52328,13,5],[52934,19,2],[53092,22,4],[53487,27,3],[53642,31,2],[53778,34,10],[54717,45,5],[55205,51,3],[55428,55,3],[55699,59,5],[56137,65,6],[57955,73,4],[58418,78,3],[58581,82,7],[59087,90,4],[59466,95,11],[60321,107,1],[60426,109,10],[61385,120,2],[61534,123,3],[61819,127,4],[63502,133,8],[64133,142,2],[64271,145,10],[65213,156,4],[65529,161,3],[65713,165,3],[65981,169,1],[66081,171,4],[66443,176,5],[66992,182,9],[68910,193,1],[69002,195,7],[69607,203,5],[70114,209,7],[70797,217,2],[70993,220,4],[71298,225,3],[71565,229,1],[71659,231,5],[72305,237,4],[72615,242,7],[73147,250,4],[73481,255,7]]]]},"as-arvores-escolhem-um-rei":{"audio":"audio/as-arvores-escolhem-um-rei.mp3?v=8d6938b52514","quadros":[[0,"Depois que os homens de Siquém fizeram Abimeleque rei, Jotão sobe ao monte Gerizim e conta uma fábula. As árvores querem escolher um rei para governá-las. Primeiro oferecem a função à oliveira, que responde lembrando o valor do azeite que já produz.",[[106,0,6],[701,7,3],[839,11,2],[1039,14,6],[1480,21,2],[1623,24,6],[2049,31,7],[2686,39,10],[3370,50,3],[4049,55,5],[4499,61,4],[4976,66,2],[5125,69,5],[5548,75,7],[6188,83,1],[6295,85,5],[6772,91,3],[6987,95,6],[8810,103,2],[9020,106,7],[9702,114,6],[10126,121,8],[10741,130,2],[10895,133,3],[11191,137,4],[11508,142,11],[13582,155,8],[14213,164,8],[15019,173,1],[15081,175,6],[15662,182,1],[15794,184,8],[16842,194,3],[17015,198,8],[17781,207,9],[18473,217,1],[18549,219,5],[19023,225,2],[19172,228,6],[19773,235,3],[19946,239,2],[20143,242,6]]],[22010,"As árvores procuram a figueira e depois a videira. Cada uma prefere continuar oferecendo seu fruto. A figueira mantém os figos doces e a videira mantém o vinho. Depois dessas recusas, as árvores chegam ao espinheiro com a mesma proposta.",[[22010,0,2],[22220,3,7],[22882,11,8],[23576,20,1],[23638,22,8],[24371,31,1],[24478,33,6],[25063,40,1],[25144,42,7],[26892,51,4],[27296,56,3],[27505,60,7],[28156,68,9],[28905,78,10],[29804,89,3],[30071,93,5],[31797,100,1],[31888,102,8],[32519,111,6],[32978,118,2],[33188,121,5],[33702,127,5],[34332,133,1],[34437,135,1],[34511,137,7],[35075,145,6],[35538,152,1],[35625,154,5],[37203,161,6],[37801,168,6],[38313,175,7],[39478,184,2],[39707,187,7],[40338,195,6],[40802,202,2],[40971,205,10],[41728,216,3],[41989,220,1],[42076,222,5],[42569,228,8]]],[44548,"O espinheiro aceita e convida as árvores a tomar abrigo à sua sombra. Em seguida, ameaça lançar fogo contra os cedros. Jotão aplica a fábula à escolha de Abimeleque. Ele questiona a lealdade de Siquém com a família de Gideão e antevê a destruição dos aliados infiéis.",[[44548,0,1],[44648,2,10],[45405,13,6],[46118,20,1],[46225,22,7],[46779,30,2],[46977,33,7],[47618,41,1],[47705,43,5],[48145,49,6],[48764,56,1],[48857,58,3],[49172,62,6],[50914,70,2],[51068,73,7],[52034,82,6],[52705,89,6],[53213,96,4],[53772,101,6],[54267,108,2],[54434,111,6],[56315,119,5],[56768,125,6],[57407,132,1],[57502,134,6],[58192,141,1],[58273,143,7],[58852,151,2],[59033,154,10],[60912,166,3],[61166,170,9],[61885,180,1],[61946,182,8],[62726,191,2],[62874,194,6],[63336,201,3],[63598,205,1],[63661,207,7],[64281,215,2],[64444,218,6],[64985,225,1],[65121,227,6],[65640,234,1],[65715,236,10],[66615,247,3],[66865,251,7],[67552,259,7]]]]},"a-cordeirinha-do-pobre":{"audio":"audio/a-cordeirinha-do-pobre.mp3?v=fbdf9b1ee76a","quadros":[[0,"O profeta Natã chega à presença do rei Davi e fala de dois homens da mesma cidade. Um era rico e tinha muitos rebanhos. O pobre tinha apenas uma pequena cordeira. Ele a criava com seus filhos, e para ele ela era como uma filha.",[[108,0,1],[189,2,7],[941,10,4],[1349,15,5],[1824,21,1],[1904,23,8],[2684,32,2],[2821,35,3],[3149,39,4],[3537,44,1],[3642,46,4],[4129,51,2],[4283,54,4],[4678,59,6],[5132,66,2],[5298,69,5],[5801,75,6],[7650,83,2],[7840,86,3],[8135,90,4],[8659,95,1],[8764,97,5],[9178,103,6],[9757,110,8],[11746,120,1],[11848,122,5],[12418,128,5],[12843,134,6],[13438,141,3],[13701,145,7],[14267,153,8],[16059,163,3],[16315,167,1],[16393,169,6],[17013,176,3],[17241,180,4],[17653,185,6],[18531,193,1],[18643,195,4],[18975,200,3],[19282,204,3],[19561,208,3],[19882,212,4],[20256,217,3],[20473,221,5]]],[22120,"Um viajante chega à casa do rico. Para preparar a refeição do visitante, o anfitrião poupa seus próprios animais e toma a única cordeira do pobre. Davi se indigna ao ouvir o caso. Exige restituição e condena a falta de compaixão do homem.",[[22120,0,2],[22304,3,8],[23034,12,5],[23492,18,1],[23585,20,4],[24043,25,2],[24193,28,4],[25855,34,4],[26265,39,8],[26914,48,1],[26988,50,8],[27752,59,2],[27885,62,9],[29097,73,1],[29208,75,9],[29937,85,5],[30378,91,4],[30777,96,8],[31537,105,7],[32176,113,1],[32285,115,4],[32689,120,1],[32806,122,5],[33256,128,8],[33877,137,2],[34025,140,5],[35704,147,4],[36091,152,2],[36307,155,7],[36954,163,2],[37153,166,5],[37585,172,1],[37672,174,4],[39392,180,5],[39913,186,11],[40953,198,1],[41059,200,7],[41683,208,1],[41767,210,5],[42340,216,2],[42509,219,9],[43306,229,2],[43493,232,5]]],[44987,"Natã diz a Davi que ele é o homem da história. Confronta o rei pelo que fez a Urias e por tomar Bate-Seba. Davi reconhece que pecou contra Deus. A justiça que ele foi capaz de exigir ao ouvir a fábula agora alcança sua própria conduta.",[[44987,0,4],[45381,5,3],[45737,9,1],[45825,11,4],[46200,16,3],[46430,20,3],[46712,24,1],[46853,26,1],[46950,28,5],[47323,34,2],[47484,37,8],[49278,47,9],[50088,57,1],[50176,59,3],[50498,63,4],[50831,68,3],[50995,72,3],[51339,76,1],[51407,78,5],[51901,84,1],[52007,86,3],[52248,90,5],[52704,96,9],[54684,107,4],[55064,112,9],[55921,122,3],[56082,126,5],[56591,132,6],[57113,139,4],[58774,145,1],[58866,147,7],[59644,155,3],[59866,159,3],[60120,163,3],[60400,167,5],[60966,173,2],[61144,176,6],[61707,183,2],[61908,186,5],[62325,192,1],[62431,194,6],[63115,201,5],[63607,207,7],[64146,215,3],[64482,219,7],[65111,227,7]]]]},"o-prisioneiro-que-escapou":{"audio":"audio/o-prisioneiro-que-escapou.mp3?v=36963100d8ba","quadros":[[0,"Um profeta cobre os olhos com uma faixa e espera pelo rei Acabe no caminho. Quando o rei passa, o homem conta que, em meio a um combate, recebeu a tarefa de guardar um prisioneiro. Se deixasse o prisioneiro escapar, pagaria com a vida ou com uma grande quantia.",[[105,0,2],[260,3,7],[1027,11,5],[1543,17,2],[1739,20,5],[2225,26,3],[2459,30,3],[2669,34,5],[3329,40,1],[3439,42,6],[4029,49,4],[4354,54,3],[4678,58,5],[5188,64,2],[5345,67,7],[7068,76,6],[7471,83,1],[7558,85,3],[7856,89,5],[8724,96,1],[8865,98,5],[9253,104,5],[9718,110,3],[10320,115,2],[10485,118,4],[10880,123,1],[10961,125,2],[11115,128,7],[12197,137,7],[12893,145,1],[12967,147,6],[13587,154,2],[13747,157,7],[14306,165,2],[14458,168,11],[16515,181,2],[16747,184,8],[17391,193,1],[17467,195,11],[18321,207,7],[19411,216,7],[19985,224,3],[20238,228,1],[20342,230,4],[20769,235,2],[20951,238,3],[21202,242,3],[21441,246,6],[21943,253,7]]],[23844,"O homem diz que estava ocupado de um lado e de outro, e, quando procurou, o prisioneiro havia sumido. Acabe ouve o relato e responde que o homem já pronunciou sua própria sentença. O rei vê a responsabilidade de guardar aquilo que lhe fora confiado.",[[23844,0,1],[23965,2,5],[24396,8,3],[24728,12,3],[24877,16,6],[25412,23,7],[26147,31,2],[26294,34,2],[26450,37,4],[26965,42,1],[27070,44,2],[27237,47,5],[28053,54,1],[28549,57,6],[28984,64,8],[29993,74,1],[30093,76,11],[30974,88,5],[31354,94,6],[33112,102,5],[33672,108,4],[34043,113,1],[34105,115,6],[34820,122,1],[34926,124,8],[35720,133,3],[35882,137,1],[35982,139,5],[36401,145,2],[36595,148,10],[37407,159,3],[37718,163,7],[38336,171,8],[40288,181,1],[40359,183,3],[40688,187,2],[40880,190,1],[40941,192,16],[42408,209,2],[42567,212,7],[43120,220,6],[43659,227,3],[43821,231,3],[43970,235,4],[44398,240,8]]],[46373,"O homem tira a faixa, e Acabe reconhece que é um profeta. O profeta aplica o relato à decisão do rei de libertar Ben-Hadade, a quem Deus havia destinado à destruição. Acabe volta para Samaria contrariado. A sentença que ele julgou evidente agora recai sobre sua própria escolha.",[[46373,0,1],[46502,2,5],[46888,8,4],[47326,13,1],[47420,15,5],[48404,22,1],[48515,24,5],[49039,30,9],[49881,40,3],[50083,44,1],[50218,46,2],[50371,49,7],[52266,58,1],[52347,60,7],[53084,68,6],[53717,75,1],[53777,77,6],[54444,84,1],[54525,86,7],[55202,94,2],[55331,97,3],[55656,101,2],[55796,104,8],[56466,113,10],[57406,125,1],[57529,127,4],[57832,132,4],[58196,137,5],[58588,143,9],[59450,153,1],[59532,155,10],[61581,167,5],[62134,173,5],[62650,179,4],[62982,184,7],[63657,192,11],[65811,205,1],[65903,207,8],[66687,216,3],[66917,220,3],[67159,224,6],[67657,231,8],[68373,240,5],[68852,246,5],[69282,252,5],[69741,258,3],[70058,262,7],[70693,270,7]]]]},"o-cardo-e-o-cedro":{"audio":"audio/o-cardo-e-o-cedro.mp3?v=d0fd660d0d80","quadros":[[0,"Depois de vencer os edomitas, Amazias, rei de Judá, desafia Jeoás, rei de Israel. Jeoás responde com uma fábula. Um cardo do Líbano envia uma proposta a um cedro. Quer que o cedro dê sua filha em casamento ao filho do cardo.",[[106,0,6],[663,7,2],[819,10,6],[1310,17,2],[1469,20,8],[2517,30,7],[3580,39,3],[3884,43,2],[4039,46,4],[4778,52,7],[5448,60,5],[6375,67,3],[6704,71,2],[6866,74,6],[7448,82,5],[7877,88,8],[8647,97,3],[8901,101,3],[9116,105,6],[10950,113,2],[11105,116,5],[11610,122,2],[11741,125,6],[12266,132,5],[12666,138,3],[12891,142,8],[13741,151,1],[13815,153,2],[13956,156,5],[15697,163,4],[15990,168,3],[16151,172,1],[16207,174,5],[16796,180,2],[17004,183,3],[17323,187,5],[17823,193,2],[17971,196,9],[18844,206,2],[18979,209,5],[19484,215,2],[19639,218,5]]],[21340,"Um animal do campo passa pelo lugar onde o cardo crescia. A história muda da proposta de casamento para o que acontece junto ao chão. O cardo, que se julga em posição de negociar com o cedro, está exposto ao passo de um animal.",[[21340,0,2],[21517,3,6],[22057,10,2],[22214,13,5],[22722,19,5],[23252,25,4],[23567,30,5],[23994,36,4],[24330,41,1],[24417,43,5],[24919,49,7],[26718,58,1],[26817,60,8],[27421,69,4],[27877,74,2],[28032,77,8],[28870,86,2],[29037,89,9],[29916,99,4],[30201,104,1],[30282,106,3],[30486,110,8],[31277,119,5],[31757,125,2],[31889,128,4],[33397,134,1],[33497,136,5],[34381,143,3],[34578,147,2],[34771,150,5],[35186,156,2],[35328,159,7],[36046,167,2],[36176,170,8],[36916,179,3],[37175,183,1],[37242,185,5],[38179,192,4],[38555,197,7],[39365,205,2],[39509,208,5],[40025,214,2],[40170,217,2],[40333,220,6]]],[42031,"O animal pisa o cardo. Jeoás adverte Amazias de que sua vitória encheu seu coração de orgulho. Aconselha que fique em casa e poupe Judá da ruína. Amazias não ouve o aviso. Na batalha que se segue, Judá é derrotado.",[[42031,0,1],[42130,2,6],[42673,9,4],[43143,14,1],[43230,16,5],[44971,23,5],[45409,29,7],[46135,37,7],[46728,45,2],[46897,48,3],[47050,52,3],[47348,56,7],[47976,64,6],[48441,71,3],[48728,75,7],[49378,83,2],[49527,86,7],[51281,95,9],[52044,105,3],[52217,109,5],[52663,115,2],[52818,118,4],[53388,123,1],[53493,125,5],[54005,131,4],[54403,136,2],[54550,139,5],[56177,146,7],[56846,154,3],[57113,158,4],[57481,163,1],[57562,165,5],[59323,172,2],[59485,175,7],[60130,183,3],[60298,187,2],[60490,190,5],[61399,197,4],[61826,202,1],[61958,204,9]]]]},"o-cantico-da-vinha":{"audio":"audio/o-cantico-da-vinha.mp3?v=b11f0a63836c","quadros":[[0,"Isaías canta sobre o amado que plantou uma vinha numa encosta fértil. Ele revolve o chão, tira as pedras e escolhe boas videiras. Constrói uma torre e abre um lugar para espremer as uvas. Tudo fica pronto para a colheita que ele espera.",[[107,0,6],[773,7,5],[1225,13,5],[1664,19,1],[1745,21,5],[2274,27,3],[2441,31,7],[2969,39,3],[3209,43,5],[3625,49,4],[3935,54,7],[4601,62,6],[6418,70,3],[6645,74,7],[7227,82,1],[7301,84,4],[8022,90,4],[8459,95,2],[8672,98,6],[9322,105,1],[9426,107,7],[10086,115,4],[10502,120,8],[12352,130,8],[13021,139,3],[13262,143,5],[13765,149,1],[13902,151,4],[14305,156,2],[14465,159,5],[14912,165,4],[15230,170,8],[15897,179,2],[16115,182,4],[17792,188,4],[18205,193,4],[18691,198,6],[19241,205,4],[19529,210,1],[19603,212,8],[20255,221,3],[20485,225,3],[20753,229,6]]],[22551,"Quando chegam os frutos, a vinha produz uvas ruins. O dono chama os moradores de Jerusalém e Judá para julgar o que aconteceu. Pergunta o que mais poderia ter feito pela vinha. Todo o cuidado da encosta torna mais grave a diferença entre o que esperava e o que encontrou.",[[22551,0,6],[22968,7,6],[23513,14,2],[23713,17,6],[24796,25,1],[24923,27,5],[25331,33,6],[25957,40,4],[26402,45,5],[28087,52,1],[28190,54,4],[28565,59,5],[29028,65,2],[29189,68,9],[29954,78,2],[30103,81,9],[30900,91,1],[31007,93,4],[31409,98,4],[31716,103,6],[32216,110,1],[32303,112,3],[32506,116,9],[34511,127,8],[35271,136,1],[35352,138,3],[35520,142,4],[35928,147,7],[36545,155,3],[36784,159,5],[37347,165,4],[37715,170,5],[39276,177,4],[39735,182,1],[39809,184,7],[40452,192,2],[40608,195,7],[41336,203,5],[41881,209,4],[42266,214,5],[42779,220,1],[42853,222,9],[43735,232,5],[44116,238,1],[44190,240,3],[44350,244,8],[45135,253,1],[45241,255,1],[45335,257,3],[45544,261,9]]],[47397,"O dono anuncia que vai retirar a cerca e deixar a vinha exposta. Isaías explica que a vinha do Senhor é Israel, e Judá é sua planta querida. Deus esperava justiça e encontrou violência. Esperava retidão e ouviu o grito de quem sofreu.",[[47397,0,1],[47499,2,4],[47901,7,7],[48494,15,3],[48675,19,3],[48949,23,7],[49565,31,1],[49647,33,5],[50218,39,1],[50319,41,6],[50838,48,1],[50951,50,5],[51359,56,7],[53284,65,6],[53888,72,7],[54592,80,3],[54754,84,1],[54853,86,5],[55257,92,2],[55387,95,6],[55873,102,1],[56016,104,6],[57003,112,1],[57101,114,4],[57493,119,1],[57623,121,3],[57942,125,6],[58442,132,7],[60145,141,4],[60514,146,8],[61249,155,7],[62085,163,1],[62188,165,9],[62934,175,9],[64867,186,8],[65584,195,7],[66267,203,1],[66404,205,5],[66844,211,1],[66930,213,5],[67411,219,2],[67570,222,4],[67861,227,6]]]]},"as-aguias-o-cedro-e-a-videira":{"audio":"audio/as-aguias-o-cedro-e-a-videira.mp3?v=8a7264267300","quadros":[[0,"Ezequiel conta uma alegoria em que uma grande águia arranca o broto mais alto de um cedro e o leva a uma terra de comércio. Depois, planta uma semente perto de muita água. Ela cresce como videira baixa, com raízes firmes e ramos voltados para a primeira águia.",[[108,0,8],[779,9,5],[1287,15,3],[1508,19,8],[2277,28,2],[2425,31,3],[2653,35,3],[2878,39,6],[3389,46,5],[3817,52,7],[4279,60,1],[4353,62,5],[4871,68,4],[5250,73,4],[5658,78,2],[5799,81,2],[5940,84,5],[6591,90,1],[6734,92,1],[6821,94,4],[7282,99,1],[7358,101,3],[7607,105,5],[8064,111,2],[8230,114,8],[10166,124,6],[11213,132,6],[11780,139,3],[11980,143,7],[12697,151,5],[13219,157,2],[13393,160,5],[13885,166,4],[15438,172,3],[15716,176,6],[16270,183,4],[16614,188,7],[17205,196,5],[18100,203,3],[18362,207,6],[19006,214,6],[19549,221,1],[19655,223,5],[20136,229,8],[20971,238,4],[21264,243,1],[21339,245,8],[21933,254,5]]],[23516,"Aparece uma segunda águia. A videira estende raízes e ramos em sua direção, esperando água. Ezequiel explica a figura com o rei da Babilônia e a aliança feita com um governante de Judá. Ao buscar apoio do Egito, o governante quebra o juramento que havia feito.",[[23516,0,7],[24247,8,3],[24453,12,7],[25085,20,5],[26716,27,1],[26808,29,7],[27376,37,7],[27948,45,6],[28598,52,1],[28698,54,5],[29206,60,2],[29367,63,3],[29657,67,7],[30657,76,9],[31408,86,4],[32957,92,8],[33613,101,7],[34332,109,1],[34394,111,6],[34979,118,3],[35240,122,1],[35321,124,3],[35659,128,2],[35821,131,9],[36648,141,1],[36750,143,1],[36828,145,7],[37458,153,5],[38017,159,3],[38278,163,2],[38428,166,10],[39248,177,2],[39410,180,4],[40944,186,2],[41116,189,6],[41659,196,5],[42210,202,2],[42359,205,5],[43281,212,1],[43378,214,10],[44231,225,6],[44788,232,1],[44862,234,9],[45685,244,3],[45898,248,5],[46294,254,5]]],[48054,"No fim, Deus promete tirar ele mesmo um ramo novo do cedro e plantá-lo num monte alto de Israel. O ramo crescerá e dará sombra às aves. O oráculo anuncia que Deus pode abater a árvore alta e elevar a baixa. A restauração começa por sua iniciativa.",[[48054,0,2],[48274,3,3],[49010,8,4],[49437,13,7],[50144,21,5],[50586,27,3],[50844,31,5],[51384,37,2],[51554,40,4],[51925,45,4],[52383,50,2],[52524,53,5],[53187,59,1],[53293,61,9],[53891,71,3],[54133,75,5],[54585,81,4],[54983,86,2],[55138,89,6],[56912,97,1],[56986,99,4],[57393,104,8],[58018,113,1],[58123,115,4],[58455,120,6],[59027,127,2],[59239,130,4],[60976,136,1],[61075,138,7],[61753,146,7],[62349,154,3],[62528,158,4],[62935,163,4],[63348,168,6],[63840,175,1],[63957,177,6],[64498,184,4],[64944,189,1],[65052,191,6],[65562,198,1],[65673,200,5],[67362,207,1],[67425,209,11],[68468,221,6],[69095,228,3],[69335,232,3],[69655,236,10]]]]}};
